export type ScanStatus = 'idle' | 'busy' | 'error';

import { GoogleGenAI, Type } from "@google/genai";

const sleep = (ms: number) => new Promise(resolve => setTimeout(resolve, ms));

/**
 * 提取名片詳細資料 - 使用 Flash 模型以確保極速與精準度
 */
export const extractCardInfo = async (
  base64Image: string, 
  mimeType: string = 'image/jpeg', 
  retryCount = 0
): Promise<any> => {
  const ai = new GoogleGenAI({ apiKey: process.env.API_KEY });
  const model = 'gemini-3-flash-preview';

  try {
    const response = await ai.models.generateContent({
      model,
      contents: {
        parts: [
          {
            inlineData: {
              mimeType: mimeType,
              data: base64Image,
            },
          },
          {
            text: `你是一位專業的名片資料分析專家，專門為 QS Hub 系統處理全球名片。

【嚴格規則】：
1. 提取名片文字填入對應欄位。若名片為雙語，欄位內容請「優先提取英文」。
2. 針對「職稱、公司、部門、產業、國家、學科」提供高品質中文譯名至 translations 物件。
3. 摘要 (reasoning) 請用繁體中文，解釋你如何分類與提取關鍵資訊。

【稱謂 (prefix) 規則】：
- 僅提取名片上明確標註的稱謂 (如 Mr., Dr., Prof.)。若無標註，請保持空白，嚴禁猜測。

【電子郵件篩選規則】：
- 僅保留一個最主要的信箱。
- 類別為 academic：優先保留 .edu 信箱。
- 其他類別：優先保留非 .edu 的商務信箱。

請以 JSON 格式回傳。`,
          },
        ],
      },
      config: {
        responseMimeType: "application/json",
        responseSchema: {
          type: Type.OBJECT,
          properties: {
            prefix: { type: Type.STRING },
            firstName: { type: Type.STRING },
            lastName: { type: Type.STRING },
            title: { type: Type.STRING },
            company: { type: Type.STRING },
            department: { type: Type.STRING },
            industry: { type: Type.STRING },
            country: { type: Type.STRING },
            email: { type: Type.STRING },
            subject: { type: Type.STRING },
            phone: { type: Type.STRING },
            website: { type: Type.STRING },
            address: { type: Type.STRING },
            category: { type: Type.STRING, enum: ["employer", "academic", "staff"] },
            reasoning: { type: Type.STRING },
            translations: {
              type: Type.OBJECT,
              properties: {
                title: { type: Type.STRING },
                company: { type: Type.STRING },
                department: { type: Type.STRING },
                industry: { type: Type.STRING },
                subject: { type: Type.STRING },
                country: { type: Type.STRING }
              }
            }
          },
          required: ["firstName", "lastName", "title", "company", "category", "reasoning", "translations"],
        },
      },
    });

    const text = response.text;
    if (!text) throw new Error("AI 回應為空");
    return JSON.parse(text);

  } catch (error: any) {
    const errorMessage = error?.message || "";
    if (errorMessage.includes("Requested entity was not found")) {
        throw new Error("API_KEY_INVALID");
    }
    if ((errorMessage.includes("503") || errorMessage.includes("rate limit")) && retryCount < 2) {
      await sleep(2000 * (retryCount + 1));
      return extractCardInfo(base64Image, mimeType, retryCount + 1);
    }
    throw error;
  }
};

/**
 * AI 自動偵測定位
 */
export const detectBusinessCards = async (base64Image: string, mimeType: string = 'image/jpeg'): Promise<{ymin: number, xmin: number, ymax: number, xmax: number}[]> => {
  const ai = new GoogleGenAI({ apiKey: process.env.API_KEY });

  try {
    const response = await ai.models.generateContent({
      model: 'gemini-3-flash-preview', 
      contents: {
        parts: [
          {
            inlineData: {
              mimeType: mimeType,
              data: base64Image,
            },
          },
          {
            text: "Detect all business cards in this image. Return their bounding boxes as a JSON array of [ymin, xmin, ymax, xmax] in normalized coordinates (0-1000).",
          },
        ],
      },
      config: {
        responseMimeType: "application/json",
        responseSchema: {
          type: Type.OBJECT,
          properties: {
            boxes: {
              type: Type.ARRAY,
              items: {
                type: Type.OBJECT,
                properties: {
                  ymin: { type: Type.NUMBER },
                  xmin: { type: Type.NUMBER },
                  ymax: { type: Type.NUMBER },
                  xmax: { type: Type.NUMBER },
                },
                required: ["ymin", "xmin", "ymax", "xmax"]
              }
            }
          }
        }
      }
    });

    const text = response.text;
    if (!text) return [];
    const data = JSON.parse(text);
    return data.boxes || [];
  } catch (e) {
    console.warn("AI Detection failed:", e);
    return [];
  }
};

import React, { useState, useEffect, useRef, useMemo } from 'react';
import { BusinessCardData, ProcessingTask } from './types';
import { extractCardInfo, detectBusinessCards } from './services/geminiService';
import CameraScanner from './components/CameraScanner';
import * as pdfjsLib from 'pdfjs-dist';

// Config PDF.js worker
const pdfjs = (pdfjsLib as any).default || pdfjsLib;
if (pdfjs.GlobalWorkerOptions) {
    pdfjs.GlobalWorkerOptions.workerSrc = `https://esm.sh/pdfjs-dist@3.11.174/build/pdf.worker.min.js`;
}

const DB_NAME = 'QSHubDB_V1_0';
const STORE_NAME = 'cards';

const getDB = (): Promise<IDBDatabase> => {
  return new Promise((resolve, reject) => {
    try {
      const request = indexedDB.open(DB_NAME, 6);
      request.onupgradeneeded = (e: any) => {
        const db = request.result;
        if (!db.objectStoreNames.contains(STORE_NAME)) {
          db.createObjectStore(STORE_NAME, { keyPath: 'id' });
        }
      };
      request.onsuccess = () => resolve(request.result);
      request.onerror = () => reject(request.error);
    } catch (e) { reject(e); }
  });
};

const saveCardToDB = async (card: BusinessCardData) => {
  try {
    const db = await getDB();
    const tx = db.transaction(STORE_NAME, 'readwrite');
    tx.objectStore(STORE_NAME).put(card);
  } catch (e) { console.warn("DB Save Error", e); }
};

const deleteCardFromDB = async (id: string) => {
  try {
    const db = await getDB();
    const tx = db.transaction(STORE_NAME, 'readwrite');
    tx.objectStore(STORE_NAME).delete(id);
  } catch (e) { console.warn("DB Delete Error", e); }
};

const getCardsMetadataFromDB = async (): Promise<BusinessCardData[]> => {
  try {
    const db = await getDB();
    return new Promise((resolve) => {
      const tx = db.transaction(STORE_NAME, 'readonly');
      const store = tx.objectStore(STORE_NAME);
      const items: BusinessCardData[] = [];
      const request = store.openCursor();
      request.onsuccess = (event: any) => {
        const cursor = event.target.result;
        if (cursor) {
          const { imageUrl, ...rest } = cursor.value;
          items.push(rest as BusinessCardData);
          cursor.continue();
        } else {
          resolve(items);
        }
      };
      request.onerror = () => resolve([]);
    });
  } catch (e) { return []; }
};

const getCardById = async (id: string): Promise<BusinessCardData | null> => {
  try {
    const db = await getDB();
    return new Promise((resolve) => {
      const tx = db.transaction(STORE_NAME, 'readonly');
      const store = tx.objectStore(STORE_NAME);
      const req = store.get(id);
      req.onsuccess = () => resolve(req.result || null);
      req.onerror = () => resolve(null);
    });
  } catch (e) { return null; }
};

type ViewMode = 'camera' | 'file' | 'detail' | 'tasks' | 'cropper';

interface CropRegion {
  id: string;
  x: number;
  y: number;
  w: number;
  h: number;
}

const App: React.FC = () => {
  const [cards, setCards] = useState<BusinessCardData[]>([]);
  const [selectedCardData, setSelectedCardData] = useState<BusinessCardData | null>(null);
  const [tasks, setTasks] = useState<ProcessingTask[]>([]);
  const [selectedCardId, setSelectedCardId] = useState<string | null>(null);
  const [viewMode, setViewMode] = useState<ViewMode>('file');
  const [isProcessing, setIsProcessing] = useState(false);
  const [isSidebarOpen, setIsSidebarOpen] = useState(false);
  const [isMobile, setIsMobile] = useState(window.innerWidth < 1024);
  const [rotation, setRotation] = useState(0);
  const [activeCategory, setActiveCategory] = useState<'employer' | 'academic' | 'staff'>('employer');
  const [isExporting, setIsExporting] = useState(false);
  const [isImageZoomed, setIsImageZoomed] = useState(false);

  const filesMap = useRef<Map<string, File | Blob>>(new Map());
  const fileInputRef = useRef<HTMLInputElement>(null);
  const imgContainerRef = useRef<HTMLDivElement>(null);
  const [containerDim, setContainerDim] = useState({ w: 0, h: 0 });

  // Cropper States
  const [cropperImage, setCropperImage] = useState<string | null>(null);
  const [cropRegions, setCropRegions] = useState<CropRegion[]>([]);
  const [isDrawing, setIsDrawing] = useState(false);
  const [isMoving, setIsMoving] = useState(false);
  const [isResizing, setIsResizing] = useState<string | null>(null); // Handle corner: tl, tr, bl, br
  const [activeCropId, setActiveCropId] = useState<string | null>(null);
  const [startPos, setStartPos] = useState({ x: 0, y: 0 });
  const [initialRect, setInitialRect] = useState<CropRegion | null>(null);
  const [currentRect, setCurrentRect] = useState<CropRegion | null>(null);
  const cropperImgRef = useRef<HTMLImageElement>(null);
  const [pdfDoc, setPdfDoc] = useState<any>(null);
  const [currentPdfPage, setCurrentPdfPage] = useState(1);
  const [isRenderingPdf, setIsRenderingPdf] = useState(false);
  const [isAiDetecting, setIsAiDetecting] = useState(false);

  const isLine = useMemo(() => /Line/i.test(navigator.userAgent), []);

  useEffect(() => {
    const handleResize = () => setIsMobile(window.innerWidth < 1024);
    window.addEventListener('resize', handleResize);
    const loadInitialData = async () => {
      const savedCards = await getCardsMetadataFromDB();
      if (savedCards && savedCards.length > 0) {
        setCards(savedCards.sort((a, b) => b.scannedAt - a.scannedAt));
      }
    };
    loadInitialData();
    return () => window.removeEventListener('resize', handleResize);
  }, []);

  useEffect(() => {
    setRotation(0);
    if (selectedCardId) {
      if (selectedCardData?.id !== selectedCardId) {
        getCardById(selectedCardId).then(data => {
          if (data) setSelectedCardData(data);
        });
      }
    } else {
      setSelectedCardData(null);
    }
  }, [selectedCardId]);

  // Image Container Resize Observer for Detail View
  useEffect(() => {
    if (viewMode === 'detail' && imgContainerRef.current) {
        const ro = new ResizeObserver(entries => {
            for (const entry of entries) {
                setContainerDim({ w: entry.contentRect.width, h: entry.contentRect.height });
            }
        });
        ro.observe(imgContainerRef.current);
        return () => ro.disconnect();
    }
  }, [viewMode]);

  const handleDeleteCard = async (e: React.MouseEvent, id: string) => {
    e.stopPropagation();
    if (!window.confirm("確定要刪除這筆名片資料嗎？此動作無法復原。")) return;

    await deleteCardFromDB(id);
    setCards(prev => prev.filter(c => c.id !== id));
    if (selectedCardId === id) {
      setSelectedCardId(null);
      setSelectedCardData(null);
      setViewMode('file');
    }
  };

  const performTask = async (task: ProcessingTask) => {
    if (isProcessing) return;
    setIsProcessing(true);
    setTasks(prev => prev.map(t => t.id === task.id ? { ...t, status: 'processing' } : t));
    try {
      const fileObj = filesMap.current.get(task.id);
      if (!fileObj) throw new Error("File missing");
      const reader = new FileReader();
      const base64Data = await new Promise<string>((resolve) => {
        reader.onload = () => resolve((reader.result as string).split(',')[1]);
        reader.readAsDataURL(fileObj);
      });

      const info = await extractCardInfo(base64Data, fileObj.type || 'image/jpeg');
      const newCard: BusinessCardData = {
        id: crypto.randomUUID(),
        ...info,
        scannedAt: Date.now(),
        source: 'QS Hub Scanner',
        imageUrl: `data:${fileObj.type || 'image/jpeg'};base64,${base64Data}`,
      };

      await saveCardToDB(newCard);
      const { imageUrl, ...newCardMeta } = newCard;
      setCards(prev => [newCardMeta as BusinessCardData, ...prev].sort((a,b) => b.scannedAt - a.scannedAt));
      setTasks(prev => prev.map(t => t.id === task.id ? { ...t, status: 'completed' } : t));

    } catch (err: any) {
      if (err.message === 'API_KEY_INVALID') window.aistudio?.openSelectKey();
      setTasks(prev => prev.map(t => t.id === task.id ? { ...t, status: 'error', error: err.message } : t));
    } finally { setIsProcessing(false); }
  };

  useEffect(() => {
    if (!isProcessing) {
      const nextTask = tasks.find(t => t.status === 'pending');
      if (nextTask) performTask({...nextTask}); 
    }
  }, [tasks, isProcessing]); 

  const handleShareOrExport = async (targetCategory: 'employer' | 'academic' | 'staff' | 'all') => {
    const targetCards = targetCategory === 'all' ? cards : cards.filter(c => c.category === targetCategory);
    if (targetCards.length === 0) return;

    setIsExporting(true);
    try {
      const XLSX = await import('xlsx');
      let exportData: any[];

      if (targetCategory === 'all') {
        exportData = targetCards.map(c => ({
          '來源 (Source)': c.source || 'QS Hub Scanner',
          '類別 (Category)': c.category,
          '稱謂 (Title/Prefix)': c.prefix || '',
          '姓氏 (Last Name)': c.lastName || '',
          '名字 (First Name)': c.firstName || '',
          '職稱 (Job Title)': c.title || '',
          '公司/機構 (Company)': c.company || '',
          '部門 (Department)': c.department || '',
          '產業 (Industry)': c.industry || '',
          '學科 (Subject)': c.subject || '',
          '電子郵件 (Email)': c.email || '',
          '電話 (Phone)': c.phone || '',
          '國家/地區 (Country)': c.country || '',
          '網站 (Website)': c.website || '',
          '地址 (Address)': c.address || '',
          '備註 (Notes)': c.notes || ''
        }));
      } else if (targetCategory === 'academic') {
        exportData = targetCards.map(c => ({
          'Source': c.source || 'QS Hub Scanner', 'Title': c.prefix || '', 'First Name': c.firstName || '', 'Last Name': c.lastName || '', 'Job Title': c.title || '', 'Department': c.department || '', 'Institution': c.company || '', 'Country or Territory': c.country || '', 'Email': c.email || '', 'Subject': c.subject || '', 'Phone': c.phone || '',
        }));
      } else {
        exportData = targetCards.map(c => ({
          'Source': c.source || 'QS Hub Scanner', 'Title': c.prefix || '', 'First Name': c.firstName || '', 'Last Name': c.lastName || '', 'Position': c.title || '', 'Industry': c.industry || '', 'Company Name': c.company || '', 'Country or Territory': c.country || '', 'Email': c.email || '', 'Phone': c.phone || '',
        }));
      }

      const ws = XLSX.utils.json_to_sheet(exportData);
      const wb = XLSX.utils.book_new();
      XLSX.utils.book_append_sheet(wb, ws, "QS_Data_Export");
      const fileName = `QS_Export_${targetCategory}_${new Date().toISOString().split('T')[0]}.xlsx`;

      try { XLSX.writeFile(wb, fileName); } 
      catch (writeErr) { if (isLine) alert("LINE 內建瀏覽器限制下載，請改用一般瀏覽器。"); else throw writeErr; }

    } catch (err: any) { alert("匯出失敗：" + err.message); } 
    finally { setIsExporting(false); }
  };

  const autoDetectInCropper = async (b64: string) => {
    setIsAiDetecting(true);
    try {
      const boxes = await detectBusinessCards(b64.split(',')[1]);
      const regions: CropRegion[] = boxes.map(box => ({
        id: crypto.randomUUID(),
        x: (box.xmin / 1000) * 100,
        y: (box.ymin / 1000) * 100,
        w: ((box.xmax - box.xmin) / 1000) * 100,
        h: ((box.ymax - box.ymin) / 1000) * 100
      }));
      setCropRegions(regions);
    } catch (e) { console.warn(e); } 
    finally { setIsAiDetecting(false); }
  };

  const renderPdfPage = async (pdf: any, pageNum: number) => {
    setIsRenderingPdf(true);
    try {
        const page = await pdf.getPage(pageNum);
        const scale = 2;
        const viewport = page.getViewport({ scale });
        const canvas = document.createElement('canvas');
        const context = canvas.getContext('2d');
        canvas.height = viewport.height;
        canvas.width = viewport.width;

        if (context) {
            await page.render({ canvasContext: context, viewport }).promise;
            const b64 = canvas.toDataURL('image/jpeg');
            setCropperImage(b64);
            setCropRegions([]);
            autoDetectInCropper(b64);
        }
    } catch (e) { alert("無法讀取 PDF 頁面"); } 
    finally { setIsRenderingPdf(false); }
  };

  const handleFileUpload = async (e: React.ChangeEvent<HTMLInputElement>) => {
    const files = e.target.files;
    if (!files || files.length === 0) return;

    const firstFile = files[0];
    if (firstFile.type === 'application/pdf') {
        const reader = new FileReader();
        reader.onload = async (ev) => {
            const typedarray = new Uint8Array(ev.target?.result as ArrayBuffer);
            try {
                const pdf = await pdfjs.getDocument(typedarray).promise;
                setPdfDoc(pdf);
                setCurrentPdfPage(1);
                await renderPdfPage(pdf, 1);
                setViewMode('cropper');
            } catch (err) { alert("PDF 解析失敗"); }
        };
        reader.readAsArrayBuffer(firstFile);
        if (fileInputRef.current) fileInputRef.current.value = '';
        return;
    }

    if (files.length === 1) {
        const reader = new FileReader();
        reader.onload = (event) => {
            const b64 = event.target?.result as string;
            setCropperImage(b64);
            setCropRegions([]);
            setViewMode('cropper');
            autoDetectInCropper(b64);
        };
        reader.readAsDataURL(firstFile);
        if (fileInputRef.current) fileInputRef.current.value = '';
        return;
    }

    const newTasks: ProcessingTask[] = [];
    for (const f of Array.from(files) as File[]) {
      const id = crypto.randomUUID();
      filesMap.current.set(id, f);
      const previewUrl = await new Promise<string>((res) => {
        const reader = new FileReader();
        reader.onload = (ev) => res(ev.target?.result as string);
        reader.readAsDataURL(f);
      });
      newTasks.push({ id, fileName: f.name, status: 'pending', progress: 0, batchIndex: 1, previewUrl });
    }
    setTasks(prev => [...prev, ...newTasks]);
    setViewMode('tasks');
    if (fileInputRef.current) fileInputRef.current.value = '';
  };

  const getMousePos = (e: React.MouseEvent | React.TouchEvent) => {
    if (!cropperImgRef.current) return { x: 0, y: 0 };
    const rect = cropperImgRef.current.getBoundingClientRect();
    const clientX = 'touches' in e ? e.touches[0].clientX : (e as React.MouseEvent).clientX;
    const clientY = 'touches' in e ? e.touches[0].clientY : (e as React.MouseEvent).clientY;
    return {
      x: ((clientX - rect.left) / rect.width) * 100,
      y: ((clientY - rect.top) / rect.height) * 100
    };
  };

  const handleCropStart = (e: React.MouseEvent | React.TouchEvent, action: 'draw' | 'move' | 'resize' = 'draw', cropId?: string, handle?: string) => {
    const pos = getMousePos(e);
    setStartPos(pos);
    if (action === 'draw') {
        setCurrentRect({ id: 'temp', x: pos.x, y: pos.y, w: 0, h: 0 });
        setIsDrawing(true);
        setActiveCropId(null);
    } else if (action === 'move' && cropId) {
        const crop = cropRegions.find(r => r.id === cropId);
        if (crop) { setInitialRect({ ...crop }); setIsMoving(true); setActiveCropId(cropId); }
    } else if (action === 'resize' && cropId && handle) {
        const crop = cropRegions.find(r => r.id === cropId);
        if (crop) { setInitialRect({ ...crop }); setIsResizing(handle); setActiveCropId(cropId); }
    }
  };

  const handleCropMove = (e: React.MouseEvent | React.TouchEvent) => {
    const pos = getMousePos(e);
    if (isDrawing && currentRect) {
        setCurrentRect({ ...currentRect, x: Math.min(pos.x, startPos.x), y: Math.min(pos.y, startPos.y), w: Math.abs(pos.x - startPos.x), h: Math.abs(pos.y - startPos.y) });
    } else if (isMoving && activeCropId && initialRect) {
        setCropRegions(prev => prev.map(r => r.id === activeCropId ? { ...r, x: Math.max(0, Math.min(100 - r.w, initialRect.x + (pos.x - startPos.x))), y: Math.max(0, Math.min(100 - r.h, initialRect.y + (pos.y - startPos.y))) } : r));
    } else if (isResizing && activeCropId && initialRect) {
        const dx = pos.x - startPos.x; const dy = pos.y - startPos.y;
        setCropRegions(prev => prev.map(r => {
            if (r.id !== activeCropId) return r;
            let { x, y, w, h } = initialRect;
            if (isResizing.includes('t')) { const newY = Math.max(0, y + dy); h = h + (y - newY); y = newY; }
            if (isResizing.includes('b')) { h = Math.max(1, Math.min(100 - y, h + dy)); }
            if (isResizing.includes('l')) { const newX = Math.max(0, x + dx); w = w + (x - newX); x = newX; }
            if (isResizing.includes('r')) { w = Math.max(1, Math.min(100 - x, w + dx)); }
            return { ...r, x, y, w, h };
        }));
    }
  };

  const handleCropEnd = () => {
    if (isDrawing && currentRect && currentRect.w > 2 && currentRect.h > 2) {
        const newCrop = { ...currentRect, id: crypto.randomUUID() };
        setCropRegions(prev => [...prev, newCrop]);
        setActiveCropId(newCrop.id);
    }
    setIsDrawing(false); setIsMoving(false); setIsResizing(null); setCurrentRect(null);
  };

  const processCrops = async () => {
    if (!cropperImage || !cropperImgRef.current) return;
    const sourceImg = new Image();
    sourceImg.src = cropperImage;
    await new Promise(r => sourceImg.onload = r);
    const newTasks: ProcessingTask[] = [];
    for (let i = 0; i < cropRegions.length; i++) {
        const crop = cropRegions[i];
        const canvas = document.createElement('canvas');
        const rX = (crop.x / 100) * sourceImg.naturalWidth; const rY = (crop.y / 100) * sourceImg.naturalHeight;
        const rW = (crop.w / 100) * sourceImg.naturalWidth; const rH = (crop.h / 100) * sourceImg.naturalHeight;
        canvas.width = rW; canvas.height = rH;
        const ctx = canvas.getContext('2d');
        if (ctx) {
            ctx.drawImage(sourceImg, rX, rY, rW, rH, 0, 0, rW, rH);
            const blob = await new Promise<Blob | null>(res => canvas.toBlob(res, 'image/jpeg', 0.95));
            if (blob) {
                const id = crypto.randomUUID(); filesMap.current.set(id, blob);
                newTasks.push({ id, fileName: `CROP_${i+1}.jpg`, status: 'pending', progress: 0, batchIndex: 1, previewUrl: URL.createObjectURL(blob) });
            }
        }
    }
    setTasks(prev => [...prev, ...newTasks]); setPdfDoc(null); setCropperImage(null); setViewMode('tasks');
  };

  const visibleCards = useMemo(() => cards.filter(c => c.category === activeCategory), [cards, activeCategory]);

  return (
    <div className="flex h-full w-full overflow-hidden bg-[#f8fafc] text-slate-900 font-sans">
