      <aside className={`fixed inset-0 z-[100] lg:relative lg:translate-x-0 transition-transform duration-300 ease-[cubic-bezier(0.2,0.8,0.2,1)] bg-white flex flex-col border-r border-slate-200 lg:w-[320px] shadow-2xl lg:shadow-none ${isSidebarOpen ? 'translate-x-0' : '-translate-x-full lg:translate-x-0'}`}>
