                 <i className="fa-solid fa-bahai text-lg animate-[spin_10s_linear_infinite]"></i>
               </div>
               <div className="min-w-0">
                 <h2 className="text-[15px] font-bold text-slate-900 tracking-tight leading-none mb-1">QS HUB</h2>
                 <p className="text-[10px] font-medium text-slate-400 tracking-wide uppercase">Scanner Pro</p>
               </div>
            </div>
            {isMobile && <button onClick={() => setIsSidebarOpen(false)} className="w-10 h-10 flex items-center justify-center bg-slate-50 hover:bg-slate-100 rounded-full text-slate-400 active:bg-slate-200"><i className="fa-solid fa-xmark text-lg"></i></button>}
          </div>

