                            </div>
                        )}
                        <button onClick={() => { setViewMode('file'); setCropperImage(null); setPdfDoc(null); }} className="px-4 py-2 text-xs font-bold text-slate-500 hover:bg-slate-100 rounded-lg">取消</button>
                        <button onClick={processCrops} disabled={cropRegions.length === 0} className="px-6 py-2 text-xs font-bold text-white bg-indigo-600 rounded-lg shadow-lg disabled:opacity-50 flex items-center gap-2">開始批次分析 ({cropRegions.length})</button>
                    </div>
                </div>
                <div className="flex-1 overflow-auto p-12 flex items-start justify-center relative select-none bg-slate-200/50" onMouseDown={(e) => { if (e.target === e.currentTarget) handleCropStart(e, 'draw'); }}>
                    <div className="relative shadow-2xl bg-white">
                        {isRenderingPdf && <div className="absolute inset-0 bg-white/80 z-[60] flex items-center justify-center backdrop-blur-sm animate-fadeIn"><i className="fa-solid fa-circle-notch fa-spin text-3xl text-indigo-500"></i></div>}
                        <img ref={cropperImgRef} src={cropperImage} className="max-w-none w-auto h-auto block select-none pointer-events-none" style={{ maxHeight: 'calc(100vh - 180px)' }} draggable={false} />
                        <div className="absolute inset-0 z-10" onMouseDown={(e) => handleCropStart(e, 'draw')}></div>
                        {cropRegions.map(crop => (
                            <div key={crop.id} className={`absolute border-2 z-20 group ${activeCropId === crop.id ? 'border-indigo-500 bg-indigo-500/10' : 'border-emerald-400 bg-emerald-400/10 hover:border-indigo-400'}`} style={{ left: `${crop.x}%`, top: `${crop.y}%`, width: `${crop.w}%`, height: `${crop.h}%` }} onMouseDown={(e) => { e.stopPropagation(); handleCropStart(e, 'move', crop.id); }}>
