            </div>
          )}
        </div>

        {isImageZoomed && selectedCardData && <div className="fixed inset-0 z-[300] bg-black/95 flex items-center justify-center p-4 backdrop-blur-sm animate-fadeIn" onClick={() => setIsImageZoomed(false)}><button onClick={() => setIsImageZoomed(false)} className="absolute top-12 right-6 w-12 h-12 bg-white/10 text-white rounded-full flex items-center justify-center z-[310]"><i className="fa-solid fa-xmark"></i></button><div className="w-full h-full flex items-center justify-center overflow-auto no-scrollbar"><img src={selectedCardData.imageUrl} className="max-w-none w-full lg:w-auto lg:h-[90vh] object-contain" style={{ transform: `rotate(${rotation}deg)` }} /></div></div>}
      </main>

      {isMobile && isSidebarOpen && <div className="fixed inset-0 bg-slate-900/50 backdrop-blur-sm z-[90] animate-fadeIn" onClick={() => setIsSidebarOpen(false)} />}
      <style>{`
        .no-scrollbar::-webkit-scrollbar { display: none; }
        .custom-scrollbar::-webkit-scrollbar { width: 4px; }
        .custom-scrollbar::-webkit-scrollbar-thumb { background: #cbd5e1; border-radius: 10px; }
        @keyframes fadeIn { from { opacity: 0; } to { opacity: 1; } }
        @keyframes fadeInUp { from { opacity: 0; transform: translateY(20px); } to { opacity: 1; transform: translateY(0); } }
        @keyframes float { 0% { transform: translateY(0px); } 50% { transform: translateY(-10px); } 100% { transform: translateY(0px); } }
        .animate-fadeIn { animation: fadeIn 0.3s ease-out forwards; }
        .animate-fadeInUp { animation: fadeInUp 0.5s cubic-bezier(0.2, 0.8, 0.2, 1) forwards; }
        .animate-float { animation: float 4s ease-in-out infinite; }
      `}</style>
    </div>
  );
};

const Field = React.memo(({ label, value, translation, icon, className }: any) => {
  if (!value || (typeof value === 'string' && !value.trim())) return null;
  const [copied, setCopied] = useState(false);
  const hasValue = Boolean(value && value.trim().length > 0);
  return (
    <div className={`group min-w-0 ${className}`}>
      <div className="flex items-center justify-between mb-1.5 px-0.5"><label className="text-[10px] font-bold text-slate-400 uppercase tracking-widest flex items-center gap-1.5">{icon && <i className={`fa-solid ${icon} text-indigo-300`}></i>} {label}</label>{hasValue && <button onClick={() => { navigator.clipboard.writeText(value); setCopied(true); setTimeout(() => setCopied(false), 2000); }} className={`text-[9px] font-bold uppercase ${copied ? 'text-emerald-500' : 'text-indigo-400'}`}>{copied ? 'Copied' : 'Copy'}</button>}</div>
      <div className="w-full bg-slate-50 border border-slate-200 p-3.5 rounded-xl active:scale-[0.99] relative"><div className={`text-[13px] font-semibold leading-relaxed break-all ${hasValue ? 'text-slate-700' : 'text-slate-300 italic'}`}>{hasValue ? value : 'N/A'}</div>{hasValue && translation && translation !== value && <div className="mt-2 pt-2 border-t border-slate-100 text-xs font-medium text-slate-500">{translation}</div>}</div>
    </div>
  );
});

const CompactTab = React.memo(({ label, active, count, onClick }: any) => (
