          <div className="mb-6 flex items-center justify-between bg-slate-50 p-2 rounded-lg border border-slate-100">
             <div className="flex items-center gap-2">
                <div className={`w-2 h-2 rounded-full bg-indigo-500`}></div>
                <span className="text-[10px] font-bold uppercase tracking-wider text-slate-500">AI Powered Analysis</span>
