                            <div key={crop.id} className={`absolute border-2 z-20 group ${activeCropId === crop.id ? 'border-indigo-500 bg-indigo-500/10' : 'border-emerald-400 bg-emerald-400/10 hover:border-indigo-400'}`} style={{ left: `${crop.x}%`, top: `${crop.y}%`, width: `${crop.w}%`, height: `${crop.h}%` }} onMouseDown={(e) => { e.stopPropagation(); handleCropStart(e, 'move', crop.id); }}>
                                <div className="absolute -top-1.5 -left-1.5 w-3 h-3 bg-white border-2 border-indigo-500 rounded-full cursor-nw-resize z-30" onMouseDown={(e) => { e.stopPropagation(); handleCropStart(e, 'resize', crop.id, 'tl'); }}></div>
                                <div className="absolute -top-1.5 -right-1.5 w-3 h-3 bg-white border-2 border-indigo-500 rounded-full cursor-ne-resize z-30" onMouseDown={(e) => { e.stopPropagation(); handleCropStart(e, 'resize', crop.id, 'tr'); }}></div>
                                <div className="absolute -bottom-1.5 -left-1.5 w-3 h-3 bg-white border-2 border-indigo-500 rounded-full cursor-sw-resize z-30" onMouseDown={(e) => { e.stopPropagation(); handleCropStart(e, 'resize', crop.id, 'bl'); }}></div>
                                <div className="absolute -bottom-1.5 -right-1.5 w-3 h-3 bg-white border-2 border-indigo-500 rounded-full cursor-se-resize z-30" onMouseDown={(e) => { e.stopPropagation(); handleCropStart(e, 'resize', crop.id, 'br'); }}></div>
