                                <div className="absolute top-1 left-1 pointer-events-none"><span className={`text-[8px] font-black uppercase px-1.5 py-0.5 rounded shadow-sm ${activeCropId === crop.id ? 'bg-indigo-600 text-white' : 'bg-emerald-500 text-white'}`}>Card {cropRegions.indexOf(crop) + 1}</span></div>
                            </div>
