                      {t.previewUrl ? <img src={t.previewUrl} className="w-12 h-12 rounded-lg object-cover border border-slate-200 shrink-0" alt="preview" /> : <div className={`w-12 h-12 rounded-xl flex items-center justify-center shrink-0 ${t.status === 'completed' ? 'bg-emerald-50 text-emerald-600' : 'bg-indigo-50 text-indigo-600'}`}><i className={`fa-solid ${t.status === 'completed' ? 'fa-check' : t.status === 'processing' ? 'fa-circle-notch fa-spin' : 'fa-clock'}`}></i></div>}
