                    </div>
                    {t.status === 'completed' && <button onClick={() => { setSelectedCardId(t.id); setViewMode('detail'); }} className="w-8 h-8 flex items-center justify-center text-slate-300"><i className="fa-solid fa-chevron-right"></i></button>}
