                    <button onClick={() => setRotation(r => r + 90)} className="w-9 h-9 bg-black/40 backdrop-blur-md rounded-xl flex items-center justify-center text-white border border-white/10"><i className="fa-solid fa-rotate-right"></i></button>
                    <button onClick={() => setIsImageZoomed(true)} className="w-9 h-9 bg-indigo-600 rounded-xl flex items-center justify-center text-white shadow-lg"><i className="fa-solid fa-expand"></i></button>
                  </div>
                  <div ref={imgContainerRef} className="flex-1 w-full h-full relative overflow-hidden p-4">
                    {selectedCardData.imageUrl && containerDim.w > 0 && (
                      <img src={selectedCardData.imageUrl} className="shadow-2xl transition-transform duration-300" style={{ position: 'absolute', left: '50%', top: '50%', transform: `translate(-50%, -50%) rotate(${rotation}deg)`, maxWidth: (Math.abs(rotation) % 180 === 90) ? containerDim.h : containerDim.w, maxHeight: (Math.abs(rotation) % 180 === 90) ? containerDim.w : containerDim.h, objectFit: 'contain' }} onClick={() => setIsImageZoomed(true)} />
