    <span className="text-[9px] font-bold uppercase tracking-wider truncate w-full text-center">{label}</span>
    <span className={`text-[10px] font-extrabold ${active ? 'text-indigo-600' : 'text-slate-400'}`}>{count}</span>
  </button>
));

const NavBtn = React.memo(({ icon, label, active, onClick }: any) => (
  <button onClick={onClick} className={`flex items-center gap-2 py-2 px-3 rounded-xl transition-all font-bold text-[10px] uppercase tracking-wide whitespace-nowrap active:scale-95 ${active ? 'bg-slate-900 text-white' : 'text-slate-500'}`}>
    <i className={`fa-solid ${icon}`}></i><span className="hidden sm:inline">{label}</span>
