                {isMobile && <NavBtn icon="fa-camera" label="掃描" active={viewMode === 'camera'} onClick={() => setViewMode('camera')} />}
                <NavBtn icon={isMobile ? "fa-upload" : "fa-print"} label={isMobile ? "上傳" : "掃描匯入"} active={viewMode === 'file'} onClick={() => setViewMode('file')} />
                <NavBtn icon="fa-list-check" label="任務" active={viewMode === 'tasks'} onClick={() => setViewMode('tasks')} />
                {selectedCardId && (
                  <>
                    <div className="w-px h-4 bg-slate-300 mx-1 shrink-0"></div>
                    <NavBtn icon="fa-id-card" label="核對" active={viewMode === 'detail'} onClick={() => setViewMode('detail')} />
                  </>
                )}
