           </div>
        </header>

        <div className="flex-1 relative overflow-hidden">
          {viewMode === 'camera' && (
            <div className="h-full p-4 lg:p-8 animate-fadeIn">
              <CameraScanner onCapture={async (b64) => { 
                  const id = crypto.randomUUID(); const res = await fetch(`data:image/jpeg;base64,${b64}`);
                  const blob = await res.blob(); filesMap.current.set(id, blob);
                  setTasks(prev => [...prev, { id, fileName: `SCAN_${Date.now()}`, status: 'pending', progress: 0, batchIndex: 1, previewUrl: `data:image/jpeg;base64,${b64}` }]);
                  setViewMode('tasks');
              }} onClose={() => setViewMode('file')} />
            </div>
          )}

          {viewMode === 'file' && (
            <div className="h-full flex flex-col items-center justify-center p-4 lg:p-10 animate-fadeInUp">
              <div className="w-full max-w-2xl p-8 lg:p-16 border-2 border-dashed border-slate-200 rounded-[2.5rem] bg-white/80 backdrop-blur-lg text-center group shadow-lg cursor-pointer transition-all hover:border-indigo-300 relative overflow-hidden" onClick={() => fileInputRef.current?.click()}>
                    <div className="w-20 h-20 lg:w-24 lg:h-24 bg-gradient-to-br from-indigo-500 to-indigo-700 rounded-[2rem] flex items-center justify-center mx-auto mb-8 shadow-xl shadow-indigo-100 relative z-10 animate-float"><i className={`fa-solid ${isMobile ? 'fa-cloud-arrow-up' : 'fa-print'} text-3xl text-white`}></i></div>
                    <div className="relative z-10">
                        <h3 className="text-2xl lg:text-3xl font-extrabold text-slate-800 mb-3">{isMobile ? '上傳名片照片' : '匯入掃描檔案'}</h3>
                        <p className="text-slate-400 text-sm mb-10 max-w-sm mx-auto">支援 PDF, JPG, PNG 格式<br/><span className="text-indigo-500 font-bold"><i className="fa-solid fa-wand-magic-sparkles"></i> AI 自動定位名片位置</span></p>
                        <div className="inline-flex items-center gap-3 px-8 py-4 bg-indigo-600 text-white rounded-2xl text-sm font-bold uppercase tracking-widest shadow-lg group-hover:bg-indigo-700 transition-all">選擇檔案</div>
                    </div>
                <input type="file" ref={fileInputRef} className="hidden" accept="image/*,.pdf" multiple onChange={handleFileUpload} />
              </div>
            </div>
          )}

          {viewMode === 'cropper' && cropperImage && (
             <div className="h-full flex flex-col bg-slate-100 animate-fadeIn" onMouseMove={handleCropMove} onMouseUp={handleCropEnd} onTouchMove={handleCropMove} onTouchEnd={handleCropEnd}>
                <div className="flex items-center justify-between p-4 bg-white border-b border-slate-200 shrink-0 z-[100]">
                    <div className="flex items-center gap-4">
                        <div className="w-10 h-10 bg-indigo-50 text-indigo-600 rounded-xl flex items-center justify-center"><i className="fa-solid fa-crop-simple"></i></div>
                        <div>
                            <h2 className="text-[15px] font-bold text-slate-800">智慧裁切工具</h2>
                            <p className="text-[10px] font-bold uppercase tracking-wider text-slate-400">已自動定位 {cropRegions.length} 張名片</p>
                        </div>
                    </div>
                    <div className="flex gap-2">
                        {isAiDetecting && <div className="flex items-center gap-2 px-3 py-1.5 bg-indigo-50 text-indigo-600 rounded-lg animate-pulse"><i className="fa-solid fa-wand-magic-sparkles fa-spin text-xs"></i><span className="text-[10px] font-bold uppercase">AI 偵測中...</span></div>}
                        {pdfDoc && (
                            <div className="flex items-center gap-1 bg-slate-100 rounded-lg p-1">
                                <button disabled={currentPdfPage <= 1} onClick={() => { setCurrentPdfPage(p => p - 1); renderPdfPage(pdfDoc, currentPdfPage - 1); }} className="w-8 h-8 flex items-center justify-center rounded bg-white disabled:opacity-50"><i className="fa-solid fa-chevron-left text-xs"></i></button>
                                <span className="text-xs font-bold w-12 text-center">{currentPdfPage}/{pdfDoc.numPages}</span>
                                <button disabled={currentPdfPage >= pdfDoc.numPages} onClick={() => { setCurrentPdfPage(p => p + 1); renderPdfPage(pdfDoc, currentPdfPage + 1); }} className="w-8 h-8 flex items-center justify-center rounded bg-white disabled:opacity-50"><i className="fa-solid fa-chevron-right text-xs"></i></button>
                            </div>
                        )}
                        <button onClick={() => { setViewMode('file'); setCropperImage(null); setPdfDoc(null); }} className="px-4 py-2 text-xs font-bold text-slate-500 hover:bg-slate-100 rounded-lg">取消</button>
                        <button onClick={processCrops} disabled={cropRegions.length === 0} className="px-6 py-2 text-xs font-bold text-white bg-indigo-600 rounded-lg shadow-lg disabled:opacity-50 flex items-center gap-2">開始批次分析 ({cropRegions.length})</button>
                    </div>
                </div>
                <div className="flex-1 overflow-auto p-12 flex items-start justify-center relative select-none bg-slate-200/50" onMouseDown={(e) => { if (e.target === e.currentTarget) handleCropStart(e, 'draw'); }}>
                    <div className="relative shadow-2xl bg-white">
                        {isRenderingPdf && <div className="absolute inset-0 bg-white/80 z-[60] flex items-center justify-center backdrop-blur-sm animate-fadeIn"><i className="fa-solid fa-circle-notch fa-spin text-3xl text-indigo-500"></i></div>}
                        <img ref={cropperImgRef} src={cropperImage} className="max-w-none w-auto h-auto block select-none pointer-events-none" style={{ maxHeight: 'calc(100vh - 180px)' }} draggable={false} />
                        <div className="absolute inset-0 z-10" onMouseDown={(e) => handleCropStart(e, 'draw')}></div>
                        {cropRegions.map(crop => (
                            <div key={crop.id} className={`absolute border-2 z-20 group ${activeCropId === crop.id ? 'border-indigo-500 bg-indigo-500/10' : 'border-emerald-400 bg-emerald-400/10 hover:border-indigo-400'}`} style={{ left: `${crop.x}%`, top: `${crop.y}%`, width: `${crop.w}%`, height: `${crop.h}%` }} onMouseDown={(e) => { e.stopPropagation(); handleCropStart(e, 'move', crop.id); }}>
                                <div className="absolute -top-1.5 -left-1.5 w-3 h-3 bg-white border-2 border-indigo-500 rounded-full cursor-nw-resize z-30" onMouseDown={(e) => { e.stopPropagation(); handleCropStart(e, 'resize', crop.id, 'tl'); }}></div>
                                <div className="absolute -top-1.5 -right-1.5 w-3 h-3 bg-white border-2 border-indigo-500 rounded-full cursor-ne-resize z-30" onMouseDown={(e) => { e.stopPropagation(); handleCropStart(e, 'resize', crop.id, 'tr'); }}></div>
                                <div className="absolute -bottom-1.5 -left-1.5 w-3 h-3 bg-white border-2 border-indigo-500 rounded-full cursor-sw-resize z-30" onMouseDown={(e) => { e.stopPropagation(); handleCropStart(e, 'resize', crop.id, 'bl'); }}></div>
                                <div className="absolute -bottom-1.5 -right-1.5 w-3 h-3 bg-white border-2 border-indigo-500 rounded-full cursor-se-resize z-30" onMouseDown={(e) => { e.stopPropagation(); handleCropStart(e, 'resize', crop.id, 'br'); }}></div>
                                <button className="absolute -top-3 -right-3 w-6 h-6 bg-red-500 text-white rounded-full flex items-center justify-center text-[10px] shadow-lg z-40" onClick={(e) => { e.stopPropagation(); setCropRegions(prev => prev.filter(c => c.id !== crop.id)); }}><i className="fa-solid fa-xmark"></i></button>
                                <div className="absolute top-1 left-1 pointer-events-none"><span className={`text-[8px] font-black uppercase px-1.5 py-0.5 rounded shadow-sm ${activeCropId === crop.id ? 'bg-indigo-600 text-white' : 'bg-emerald-500 text-white'}`}>Card {cropRegions.indexOf(crop) + 1}</span></div>
                            </div>
                        ))}
                        {isDrawing && currentRect && <div className="absolute border-2 border-dashed border-indigo-500 bg-indigo-500/5 z-30 pointer-events-none" style={{ left: `${currentRect.x}%`, top: `${currentRect.y}%`, width: `${currentRect.w}%`, height: `${currentRect.h}%` }}></div>}
                    </div>
                </div>
                <div className="bg-white p-3 border-t border-slate-200 flex justify-center gap-8 text-[10px] font-bold text-slate-400 uppercase tracking-widest shrink-0">
                    <span className="flex items-center gap-2"><i className="fa-solid fa-mouse-pointer text-indigo-400"></i> 拖曳框選區域</span>
                    <span className="flex items-center gap-2"><i className="fa-solid fa-up-down-left-right text-indigo-400"></i> 移動位置</span>
                    <span className="flex items-center gap-2"><i className="fa-solid fa-maximize text-indigo-400"></i> 調整大小</span>
                </div>
             </div>
          )}

          {viewMode === 'tasks' && (
            <div className="max-w-2xl mx-auto p-4 lg:p-12 animate-fadeIn h-full overflow-y-auto pb-32">
              <div className="flex items-center justify-between mb-6"><h2 className="text-xl lg:text-2xl font-bold text-slate-800 tracking-tight">處理佇列</h2><span className="bg-indigo-100 text-indigo-700 px-3 py-1 rounded-full text-xs font-bold">{tasks.length} 項目</span></div>
              <div className="space-y-3">
                {tasks.map(t => (
                  <div key={t.id} className="p-4 bg-white border border-slate-100 rounded-2xl flex items-center justify-between shadow-sm">
                    <div className="flex items-center gap-4 min-w-0">
                      {t.previewUrl ? <img src={t.previewUrl} className="w-12 h-12 rounded-lg object-cover border border-slate-200 shrink-0" alt="preview" /> : <div className={`w-12 h-12 rounded-xl flex items-center justify-center shrink-0 ${t.status === 'completed' ? 'bg-emerald-50 text-emerald-600' : 'bg-indigo-50 text-indigo-600'}`}><i className={`fa-solid ${t.status === 'completed' ? 'fa-check' : t.status === 'processing' ? 'fa-circle-notch fa-spin' : 'fa-clock'}`}></i></div>}
                      <div className="min-w-0"><div className="font-bold text-slate-800 text-sm truncate mb-0.5">{t.fileName}</div><div className="text-[10px] font-bold uppercase tracking-wider text-slate-400">{t.status === 'completed' ? '已完成' : t.status === 'processing' ? 'AI 分析中...' : '等待中'}</div></div>
                    </div>
                    {t.status === 'completed' && <button onClick={() => { setSelectedCardId(t.id); setViewMode('detail'); }} className="w-8 h-8 flex items-center justify-center text-slate-300 transition-transform active:translate-x-1"><i className="fa-solid fa-chevron-right"></i></button>}
                  </div>
                ))}
              </div>
            </div>
          )}

          {viewMode === 'detail' && (
            <div className="h-full flex flex-col lg:flex-row overflow-hidden animate-fadeIn relative" key={selectedCardData?.id || 'empty'}>
               {isLoadingDetail && (
                 <div className="absolute inset-0 bg-white/60 backdrop-blur-[2px] z-[90] flex items-center justify-center animate-fadeIn">
                   <div className="flex flex-col items-center gap-4">
                     <div className="w-12 h-12 border-4 border-indigo-100 border-t-indigo-600 rounded-full animate-spin"></div>
                     <p className="text-xs font-bold text-indigo-600 uppercase tracking-widest">資料載入中...</p>
                   </div>
                 </div>
               )}

               {selectedCardData ? (
                 <>
                   <div className={`relative flex flex-col bg-black overflow-hidden shadow-inner ${isMobile ? 'h-[40vh] shrink-0' : 'w-[45%] h-full border-r border-slate-800'}`}>
                      <div className="absolute top-4 right-4 z-[70] flex gap-2">
                        <button onClick={() => setRotation(r => r + 90)} className="w-9 h-9 bg-black/40 backdrop-blur-md rounded-xl flex items-center justify-center text-white border border-white/10 transition-colors hover:bg-black/60"><i className="fa-solid fa-rotate-right"></i></button>
                        <button onClick={() => setIsImageZoomed(true)} className="w-9 h-9 bg-indigo-600 rounded-xl flex items-center justify-center text-white shadow-lg shadow-indigo-500/30 transition-transform active:scale-95"><i className="fa-solid fa-expand"></i></button>
