                            className="shadow-2xl transition-transform duration-300 ease-out cursor-zoom-in" 
                            style={{ 
                              position: 'absolute', 
                              left: '50%', 
                              top: '50%', 
                              transform: `translate(-50%, -50%) rotate(${rotation}deg)`, 
                              maxWidth: (Math.abs(rotation) % 180 === 90) ? containerDim.h : containerDim.w, 
                              maxHeight: (Math.abs(rotation) % 180 === 90) ? containerDim.w : containerDim.h, 
                              objectFit: 'contain' 
                            }} 
                            onClick={() => setIsImageZoomed(true)} 
                          />
                        )}
                      </div>
                   </div>
                   <div className="flex-1 overflow-y-auto custom-scrollbar bg-white p-5 lg:p-12 space-y-6">
                        <header className="border-b border-slate-100 pb-6">
                          <div className="flex items-center justify-between mb-3">
                            <span className="px-2.5 py-1 bg-indigo-50 text-indigo-600 text-[10px] font-bold uppercase rounded-md inline-block">{selectedCardData.category}</span>
                            <div className="flex items-center gap-3">
                              {!isMobile && (
