const DB_NAME = 'QSHubDB_V1_0';
const STORE_NAME = 'cards';

const getDB = (): Promise<IDBDatabase> => {
  return new Promise((resolve, reject) => {
    try {
      const request = indexedDB.open(DB_NAME, 6);
      request.onupgradeneeded = (e: any) => {
        const db = request.result;
        if (!db.objectStoreNames.contains(STORE_NAME)) {
          db.createObjectStore(STORE_NAME, { keyPath: 'id' });
        }
      };
      request.onsuccess = () => resolve(request.result);
      request.onerror = () => reject(request.error);
    } catch (e) { reject(e); }
  });
};

const saveCardToDB = async (card: BusinessCardData) => {
  try {
    const db = await getDB();
    const tx = db.transaction(STORE_NAME, 'readwrite');
    tx.objectStore(STORE_NAME).put(card);
  } catch (e) { console.warn("DB Save Error", e); }
};

const deleteCardFromDB = async (id: string) => {
  try {
    const db = await getDB();
    const tx = db.transaction(STORE_NAME, 'readwrite');
    tx.objectStore(STORE_NAME).delete(id);
  } catch (e) { console.warn("DB Delete Error", e); }
};

const clearAllCardsFromDB = async () => {
  try {
    const db = await getDB();
    const tx = db.transaction(STORE_NAME, 'readwrite');
    tx.objectStore(STORE_NAME).clear();
    return true;
  } catch (e) {
    console.warn("DB Clear Error", e);
    return false;
  }
};

const getCardsMetadataFromDB = async (): Promise<BusinessCardData[]> => {
  try {
    const db = await getDB();
    return new Promise((resolve) => {
      const tx = db.transaction(STORE_NAME, 'readonly');
      const store = tx.objectStore(STORE_NAME);
      const items: BusinessCardData[] = [];
      const request = store.openCursor();
      request.onsuccess = (event: any) => {
        const cursor = event.target.result;
        if (cursor) {
          const { imageUrl, ...rest } = cursor.value;
          items.push(rest as BusinessCardData);
          cursor.continue();
        } else {
          resolve(items);
        }
      };
      request.onerror = () => resolve([]);
    });
  } catch (e) { return []; }
};

const getCardById = async (id: string): Promise<BusinessCardData | null> => {
  try {
    const db = await getDB();
    return new Promise((resolve) => {
      const tx = db.transaction(STORE_NAME, 'readonly');
      const store = tx.objectStore(STORE_NAME);
      const req = store.get(id);
      req.onsuccess = () => resolve(req.result || null);
      req.onerror = () => resolve(null);
    });
  } catch (e) { return null; }
};

type ViewMode = 'camera' | 'file' | 'detail' | 'tasks' | 'cropper';

interface CropRegion {
  id: string;
  x: number;
  y: number;
  w: number;
  h: number;
}

const App: React.FC = () => {
  const [cards, setCards] = useState<BusinessCardData[]>([]);
  const [selectedCardData, setSelectedCardData] = useState<BusinessCardData | null>(null);
  const [tasks, setTasks] = useState<ProcessingTask[]>([]);
  const [selectedCardId, setSelectedCardId] = useState<string | null>(null);
  const [viewMode, setViewMode] = useState<ViewMode>('file');
  const [isProcessing, setIsProcessing] = useState(false);
  const [isSidebarOpen, setIsSidebarOpen] = useState(false);
  const [isMobile, setIsMobile] = useState(window.innerWidth < 1024);
  const [rotation, setRotation] = useState(0);
  const [activeCategory, setActiveCategory] = useState<'employer' | 'academic' | 'staff'>('employer');
  const [isExporting, setIsExporting] = useState(false);
  const [isImageZoomed, setIsImageZoomed] = useState(false);
  const [isLoadingDetail, setIsLoadingDetail] = useState(false);

  const filesMap = useRef<Map<string, File | Blob>>(new Map());
  const fileInputRef = useRef<HTMLInputElement>(null);
  const imgContainerRef = useRef<HTMLDivElement>(null);
  const [containerDim, setContainerDim] = useState({ w: 0, h: 0 });

  // Cropper States
  const [cropperImage, setCropperImage] = useState<string | null>(null);
  const [cropRegions, setCropRegions] = useState<CropRegion[]>([]);
  const [isDrawing, setIsDrawing] = useState(false);
  const [isMoving, setIsMoving] = useState(false);
  const [isResizing, setIsResizing] = useState<string | null>(null); 
  const [activeCropId, setActiveCropId] = useState<string | null>(null);
  const [startPos, setStartPos] = useState({ x: 0, y: 0 });
  const [initialRect, setInitialRect] = useState<CropRegion | null>(null);
  const [currentRect, setCurrentRect] = useState<CropRegion | null>(null);
  const cropperImgRef = useRef<HTMLImageElement>(null);
  const [pdfDoc, setPdfDoc] = useState<any>(null);
  const [currentPdfPage, setCurrentPdfPage] = useState(1);
  const [isRenderingPdf, setIsRenderingPdf] = useState(false);
  const [isAiDetecting, setIsAiDetecting] = useState(false);

  const isLine = useMemo(() => /Line/i.test(navigator.userAgent), []);

  useEffect(() => {
    const handleResize = () => setIsMobile(window.innerWidth < 1024);
    window.addEventListener('resize', handleResize);
    const loadInitialData = async () => {
      const savedCards = await getCardsMetadataFromDB();
      if (savedCards && savedCards.length > 0) {
        setCards(savedCards.sort((a, b) => b.scannedAt - a.scannedAt));
      }
    };
    loadInitialData();
    return () => window.removeEventListener('resize', handleResize);
  }, []);

  useEffect(() => {
    setRotation(0);
    if (selectedCardId) {
      setIsLoadingDetail(true);
      setSelectedCardData(null); 
      getCardById(selectedCardId).then(data => {
        if (data) setSelectedCardData(data);
        setIsLoadingDetail(false);
      }).catch(() => setIsLoadingDetail(false));
    } else {
      setSelectedCardData(null);
    }
  }, [selectedCardId]);

  // Image Container Resize Observer for Detail View
  useEffect(() => {
    if (viewMode === 'detail' && imgContainerRef.current) {
        const ro = new ResizeObserver(entries => {
            for (const entry of entries) {
                setContainerDim({ w: entry.contentRect.width, h: entry.contentRect.height });
            }
        });
        ro.observe(imgContainerRef.current);
        return () => ro.disconnect();
    }
  }, [viewMode]);

  const handleDeleteCard = async (e: React.MouseEvent, id: string) => {
    e.stopPropagation();
    if (!window.confirm("確定要刪除這筆名片資料嗎？此動作無法復原。")) return;

    await deleteCardFromDB(id);
    setCards(prev => prev.filter(c => c.id !== id));
    if (selectedCardId === id) {
      setSelectedCardId(null);
      setSelectedCardData(null);
      setViewMode('file');
    }
  };

  const handleClearAll = async () => {
    if (cards.length === 0) return;
    if (!window.confirm("⚠️ 警告：這將會永久刪除所有類別（Employer, Academic, Staff）的所有名片紀錄！確定要執行嗎？")) return;

    const success = await clearAllCardsFromDB();
    if (success) {
      setCards([]);
      setSelectedCardId(null);
      setSelectedCardData(null);
      setViewMode('file');
      alert("已清空所有紀錄");
    }
  };

  const performTask = async (task: ProcessingTask) => {
    if (isProcessing) return;
    setIsProcessing(true);
    setTasks(prev => prev.map(t => t.id === task.id ? { ...t, status: 'processing' } : t));
    try {
      const fileObj = filesMap.current.get(task.id);
      if (!fileObj) throw new Error("File missing");
      const reader = new FileReader();
      const base64Data = await new Promise<string>((resolve) => {
        reader.onload = () => resolve((reader.result as string).split(',')[1]);
        reader.readAsDataURL(fileObj);
      });

      const info = await extractCardInfo(base64Data, fileObj.type || 'image/jpeg');

      const newCard: BusinessCardData = {
        ...info,
        id: task.id, 
        scannedAt: Date.now(),
        source: 'QS Hub Scanner',
        imageUrl: `data:${fileObj.type || 'image/jpeg'};base64,${base64Data}`,
      };

      await saveCardToDB(newCard);
      const { imageUrl, ...newCardMeta } = newCard;

      setCards(prev => [newCardMeta as BusinessCardData, ...prev].sort((a,b) => b.scannedAt - a.scannedAt));
      setTasks(prev => prev.map(t => t.id === task.id ? { ...t, status: 'completed' } : t));

    } catch (err: any) {
      if (err.message === 'API_KEY_INVALID') window.aistudio?.openSelectKey();
      setTasks(prev => prev.map(t => t.id === task.id ? { ...t, status: 'error', error: err.message } : t));
    } finally { setIsProcessing(false); }
  };

  useEffect(() => {
    if (!isProcessing) {
      const nextTask = tasks.find(t => t.status === 'pending');
      if (nextTask) performTask({...nextTask}); 
    }
  }, [tasks, isProcessing]); 

  /**
   * 封裝 Excel 生成邏輯，回傳 File 物件
   */
  const createExcelFile = async (targetCards: BusinessCardData[], fileName: string): Promise<File> => {
    const XLSX = await import('xlsx');
    let exportData: any[];

    // 格式化數據
    exportData = targetCards.map(c => ({
      '來源 (Source)': c.source || 'QS Hub Scanner',
      '類別 (Category)': c.category,
      '稱謂 (Title/Prefix)': c.prefix || '',
      '姓氏 (Last Name)': c.lastName || '',
      '名字 (First Name)': c.firstName || '',
      '職稱 (Job Title)': c.title || '',
      '公司/機構 (Company)': c.company || '',
      '部門 (Department)': c.department || '',
      '產業 (Industry)': c.industry || '',
      '學科 (Subject)': c.subject || '',
      '電子郵件 (Email)': c.email || '',
      '電話 (Phone)': c.phone || '',
      '國家/地區 (Country)': c.country || '',
      '網站 (Website)': c.website || '',
      '地址 (Address)': c.address || '',
      '備註 (Notes)': c.notes || ''
    }));

    const ws = XLSX.utils.json_to_sheet(exportData);
    const wb = XLSX.utils.book_new();
    XLSX.utils.book_append_sheet(wb, ws, "QS_Data_Export");

    const excelBuffer = XLSX.write(wb, { bookType: 'xlsx', type: 'array' });
    const blob = new Blob([excelBuffer], { type: 'application/vnd.openxmlformats-officedocument.spreadsheetml.sheet' });

    return new File([blob], fileName, { type: blob.type });
  };

  /**
   * 處理分享或匯出：支援直接分享檔案
   */
  const handleShareOrExport = async (targetCategory: 'employer' | 'academic' | 'staff' | 'all') => {
    const targetCards = targetCategory === 'all' ? cards : cards.filter(c => c.category === targetCategory);
    if (targetCards.length === 0) return;

    setIsExporting(true);
    try {
      const fileName = `QS_Export_${targetCategory}_${new Date().toISOString().split('T')[0]}.xlsx`;
      const excelFile = await createExcelFile(targetCards, fileName);

      // 優先嘗試使用 Web Share API 分享檔案
      if (navigator.canShare && navigator.canShare({ files: [excelFile] })) {
        try {
          await navigator.share({
            files: [excelFile],
            title: 'QS Hub 數據匯出',
            text: `匯出類別: ${targetCategory}`
          });
          return; // 分享成功，結束
        } catch (shareErr) {
          console.warn("Navigator Share failed, fallback to download", shareErr);
        }
      }

      // Fallback: 下載檔案
      const XLSX = await import('xlsx');
      const ws = XLSX.utils.json_to_sheet(targetCards.map(c => ({
          '來源 (Source)': c.source || 'QS Hub Scanner', '類別 (Category)': c.category, '姓名': `${c.prefix || ''} ${c.firstName} ${c.lastName}`, '職稱': c.title, '公司': c.company, 'Email': c.email, '電話': c.phone
      })));
      const wb = XLSX.utils.book_new();
      XLSX.utils.book_append_sheet(wb, ws, "Export");

      try { XLSX.writeFile(wb, fileName); } 
      catch (writeErr) { if (isLine) alert("LINE 內建瀏覽器限制下載，請點選右上角並選擇「使用預設瀏覽器開啟」再嘗試。"); else throw writeErr; }

    } catch (err: any) { 
      alert("處理失敗：" + err.message); 
    } finally { 
      setIsExporting(false); 
    }
  };

  /**
   * 分享單張名片的 Excel
   */
  const handleShareCardExcel = async (card: BusinessCardData) => {
    setIsExporting(true);
    try {
      const fileName = `QS_Card_${card.lastName}_${card.firstName}.xlsx`;
      const excelFile = await createExcelFile([card], fileName);

      if (navigator.canShare && navigator.canShare({ files: [excelFile] })) {
        await navigator.share({
          files: [excelFile],
          title: `名片資訊 - ${card.firstName} ${card.lastName}`,
        });
      } else {
        // 下載備案
        const XLSX = await import('xlsx');
        const ws = XLSX.utils.json_to_sheet([{
            '姓名': `${card.prefix || ''} ${card.firstName} ${card.lastName}`, '職稱': card.title, '公司': card.company, 'Email': card.email, '電話': card.phone
        }]);
        const wb = XLSX.utils.book_new();
        XLSX.utils.book_append_sheet(wb, ws, "Card");
        XLSX.writeFile(wb, fileName);
      }
    } catch (e) {
      console.warn("Share failed", e);
      // 如果檔案分享失敗，嘗試文字分享
      const text = `姓名：${card.firstName} ${card.lastName}\n公司：${card.company}\nEmail：${card.email}`;
      if (navigator.share) await navigator.share({ text });
    } finally {
      setIsExporting(false);
    }
  };

  const autoDetectInCropper = async (b64: string) => {
    setIsAiDetecting(true);
    try {
      const boxes = await detectBusinessCards(b64.split(',')[1]);
      const regions: CropRegion[] = boxes.map(box => ({
        id: crypto.randomUUID(),
        x: (box.xmin / 1000) * 100,
        y: (box.ymin / 1000) * 100,
        w: ((box.xmax - box.xmin) / 1000) * 100,
        h: ((box.ymax - box.ymin) / 1000) * 100
      }));
      setCropRegions(regions);
    } catch (e) { console.warn(e); } 
    finally { setIsAiDetecting(false); }
  };

  const renderPdfPage = async (pdf: any, pageNum: number) => {
    setIsRenderingPdf(true);
    try {
        const page = await pdf.getPage(pageNum);
        const scale = 2;
        const viewport = page.getViewport({ scale });
        const canvas = document.createElement('canvas');
        const context = canvas.getContext('2d');
        canvas.height = viewport.height;
        canvas.width = viewport.width;

        if (context) {
            await page.render({ canvasContext: context, viewport }).promise;
            const b64 = canvas.toDataURL('image/jpeg');
            setCropperImage(b64);
            setCropRegions([]);
            autoDetectInCropper(b64);
        }
    } catch (e) { alert("無法讀取 PDF 頁面"); } 
    finally { setIsRenderingPdf(false); }
  };

  const handleFileUpload = async (e: React.ChangeEvent<HTMLInputElement>) => {
    const files = e.target.files;
    if (!files || files.length === 0) return;

    const firstFile = files[0];
    if (firstFile.type === 'application/pdf') {
        const reader = new FileReader();
        reader.onload = async (ev) => {
            const typedarray = new Uint8Array(ev.target?.result as ArrayBuffer);
            try {
                const pdf = await pdfjs.getDocument(typedarray).promise;
                setPdfDoc(pdf);
                setCurrentPdfPage(1);
                await renderPdfPage(pdf, 1);
                setViewMode('cropper');
            } catch (err) { alert("PDF 解析失敗"); }
        };
        reader.readAsArrayBuffer(firstFile);
        if (fileInputRef.current) fileInputRef.current.value = '';
        return;
    }

    if (files.length === 1) {
        const reader = new FileReader();
        reader.onload = (event) => {
            const b64 = event.target?.result as string;
            setCropperImage(b64);
            setCropRegions([]);
            setViewMode('cropper');
            autoDetectInCropper(b64);
        };
        reader.readAsDataURL(firstFile);
        if (fileInputRef.current) fileInputRef.current.value = '';
        return;
    }

    const newTasks: ProcessingTask[] = [];
    for (const f of Array.from(files) as File[]) {
      const id = crypto.randomUUID();
      filesMap.current.set(id, f);
      const previewUrl = await new Promise<string>((res) => {
        const reader = new FileReader();
        reader.onload = (ev) => res(ev.target?.result as string);
        reader.readAsDataURL(f);
      });
      newTasks.push({ id, fileName: f.name, status: 'pending', progress: 0, batchIndex: 1, previewUrl });
    }
    setTasks(prev => [...prev, ...newTasks]);
    setViewMode('tasks');
    if (fileInputRef.current) fileInputRef.current.value = '';
  };

  const getMousePos = (e: React.MouseEvent | React.TouchEvent) => {
    if (!cropperImgRef.current) return { x: 0, y: 0 };
    const rect = cropperImgRef.current.getBoundingClientRect();
    const clientX = 'touches' in e ? e.touches[0].clientX : (e as React.MouseEvent).clientX;
    const clientY = 'touches' in e ? e.touches[0].clientY : (e as React.MouseEvent).clientY;
    return {
      x: ((clientX - rect.left) / rect.width) * 100,
      y: ((clientY - rect.top) / rect.height) * 100
    };
  };

  const handleCropStart = (e: React.MouseEvent | React.TouchEvent, action: 'draw' | 'move' | 'resize' = 'draw', cropId?: string, handle?: string) => {
    const pos = getMousePos(e);
    setStartPos(pos);
    if (action === 'draw') {
        setCurrentRect({ id: 'temp', x: pos.x, y: pos.y, w: 0, h: 0 });
        setIsDrawing(true);
        setActiveCropId(null);
    } else if (action === 'move' && cropId) {
        const crop = cropRegions.find(r => r.id === cropId);
        if (crop) { setInitialRect({ ...crop }); setIsMoving(true); setActiveCropId(cropId); }
    } else if (action === 'resize' && cropId && handle) {
        const crop = cropRegions.find(r => r.id === cropId);
        if (crop) { setInitialRect({ ...crop }); setIsResizing(handle); setActiveCropId(cropId); }
    }
  };

  const handleCropMove = (e: React.MouseEvent | React.TouchEvent) => {
    const pos = getMousePos(e);
    if (isDrawing && currentRect) {
        setCurrentRect({ ...currentRect, x: Math.min(pos.x, startPos.x), y: Math.min(pos.y, startPos.y), w: Math.abs(pos.x - startPos.x), h: Math.abs(pos.y - startPos.y) });
    } else if (isMoving && activeCropId && initialRect) {
        setCropRegions(prev => prev.map(r => r.id === activeCropId ? { ...r, x: Math.max(0, Math.min(100 - r.w, initialRect.x + (pos.x - startPos.x))), y: Math.max(0, Math.min(100 - r.h, initialRect.y + (pos.y - startPos.y))) } : r));
    } else if (isResizing && activeCropId && initialRect) {
        const dx = pos.x - startPos.x; const dy = pos.y - startPos.y;
        setCropRegions(prev => prev.map(r => {
            if (r.id !== activeCropId) return r;
            let { x, y, w, h } = initialRect;
            if (isResizing.includes('t')) { const newY = Math.max(0, y + dy); h = h + (y - newY); y = newY; }
            if (isResizing.includes('b')) { h = Math.max(1, Math.min(100 - y, h + dy)); }
            if (isResizing.includes('l')) { const newX = Math.max(0, x + dx); w = w + (x - newX); x = newX; }
            if (isResizing.includes('r')) { w = Math.max(1, Math.min(100 - x, w + dx)); }
            return { ...r, x, y, w, h };
        }));
    }
  };

  const handleCropEnd = () => {
    if (isDrawing && currentRect && currentRect.w > 2 && currentRect.h > 2) {
        const newCrop = { ...currentRect, id: crypto.randomUUID() };
        setCropRegions(prev => [...prev, newCrop]);
        setActiveCropId(newCrop.id);
    }
    setIsDrawing(false); setIsMoving(false); setIsResizing(null); setCurrentRect(null);
  };

  const processCrops = async () => {
    if (!cropperImage || !cropperImgRef.current) return;
    const sourceImg = new Image();
    sourceImg.src = cropperImage;
    await new Promise(r => sourceImg.onload = r);
    const newTasks: ProcessingTask[] = [];
    for (let i = 0; i < cropRegions.length; i++) {
        const crop = cropRegions[i];
        const canvas = document.createElement('canvas');
        const rX = (crop.x / 100) * sourceImg.naturalWidth; const rY = (crop.y / 100) * sourceImg.naturalHeight;
        const rW = (crop.w / 100) * sourceImg.naturalWidth; const rH = (crop.h / 100) * sourceImg.naturalHeight;
        canvas.width = rW; canvas.height = rH;
        const ctx = canvas.getContext('2d');
        if (ctx) {
            ctx.drawImage(sourceImg, rX, rY, rW, rH, 0, 0, rW, rH);
            const blob = await new Promise<Blob | null>(res => canvas.toBlob(res, 'image/jpeg', 0.95));
            if (blob) {
                const id = crypto.randomUUID(); filesMap.current.set(id, blob);
                newTasks.push({ id, fileName: `CROP_${i+1}.jpg`, status: 'pending', progress: 0, batchIndex: 1, previewUrl: URL.createObjectURL(blob) });
            }
        }
    }
    setTasks(prev => [...prev, ...newTasks]); setPdfDoc(null); setCropperImage(null); setViewMode('tasks');
  };

  const visibleCards = useMemo(() => cards.filter(c => c.category === activeCategory), [cards, activeCategory]);

  return (
    <div className="flex h-full w-full overflow-hidden bg-[#f8fafc] text-slate-900 font-sans">
      {/* Sidebar */}
      <aside className={`fixed inset-0 z-[100] lg:relative lg:translate-x-0 transition-transform duration-300 ease-[cubic-bezier(0.2,0.8,0.2,1)] bg-white flex flex-col border-r border-slate-200 lg:w-[320px] shadow-2xl lg:shadow-none ${isSidebarOpen ? 'translate-x-0' : '-translate-x-full lg:translate-x-0'}`}>
        <div className="p-5 lg:p-6 bg-white/80 backdrop-blur-md border-b border-slate-100 shrink-0 z-10 sticky top-0" style={{ paddingTop: 'calc(1.25rem + var(--sat))' }}>
          <div className="flex items-center justify-between mb-4">
            <div className="flex items-center gap-3.5">
               <div className="w-10 h-10 bg-gradient-to-br from-indigo-600 to-indigo-700 rounded-xl flex items-center justify-center text-white shadow-lg shadow-indigo-200 shrink-0">
                 <i className="fa-solid fa-bahai text-lg animate-[spin_10s_linear_infinite]"></i>
               </div>
               <div className="min-w-0">
                 <h2 className="text-[15px] font-bold text-slate-900 tracking-tight leading-none mb-1">QS HUB</h2>
                 <p className="text-[10px] font-medium text-slate-400 tracking-wide uppercase">Scanner Pro</p>
               </div>
            </div>
            {isMobile && <button onClick={() => setIsSidebarOpen(false)} className="w-10 h-10 flex items-center justify-center bg-slate-50 hover:bg-slate-100 rounded-full text-slate-400 active:bg-slate-200"><i className="fa-solid fa-xmark text-lg"></i></button>}
          </div>

          <div className="mb-6 flex items-center justify-between bg-slate-50 p-2 rounded-lg border border-slate-100">
             <div className="flex items-center gap-2">
                <div className={`w-2 h-2 rounded-full bg-indigo-500`}></div>
                <span className="text-[10px] font-bold uppercase tracking-wider text-slate-500">AI Powered Analysis</span>
             </div>
             {window.aistudio && (
               <button onClick={() => window.aistudio.openSelectKey()} className="text-indigo-600 hover:text-indigo-800 transition-colors">
                  <i className="fa-solid fa-key text-xs"></i>
               </button>
             )}
          </div>

          <div className="bg-slate-100/80 p-1 rounded-xl flex gap-1 mb-4">
            <CompactTab label="Employer" active={activeCategory === 'employer'} count={cards.filter(c=>c.category==='employer').length} onClick={() => setActiveCategory('employer')} />
            <CompactTab label="Academic" active={activeCategory === 'academic'} count={cards.filter(c=>c.category==='academic').length} onClick={() => setActiveCategory('academic')} />
            <CompactTab label="Staff" active={activeCategory === 'staff'} count={cards.filter(c=>c.category==='staff').length} onClick={() => setActiveCategory('staff')} />
          </div>

          <div className="space-y-2">
            <div className="flex gap-2">
              <button onClick={() => handleShareOrExport('all')} disabled={isExporting} className="flex-1 py-3 bg-white border border-slate-200 text-slate-600 rounded-lg text-[11px] font-bold uppercase tracking-wide flex items-center justify-center gap-2 active:scale-95 transition-all hover:bg-slate-50 disabled:opacity-50">
                {isExporting ? <i className="fa-solid fa-circle-notch fa-spin"></i> : <i className="fa-solid fa-database"></i>} 全資料
              </button>
              <button onClick={() => handleShareOrExport(activeCategory)} disabled={isExporting} className="flex-1 py-3 bg-emerald-50 text-emerald-700 border border-emerald-100 rounded-lg text-[11px] font-bold uppercase tracking-wide flex items-center justify-center gap-2 active:scale-95 transition-all hover:bg-emerald-100 disabled:opacity-50">
                {isExporting ? <i className="fa-solid fa-circle-notch fa-spin"></i> : <i className="fa-solid fa-share-nodes"></i>} 匯出/分享
              </button>
            </div>
            <button 
              onClick={handleClearAll} 
              disabled={cards.length === 0}
              className="w-full py-2.5 bg-red-50 text-red-500 border border-red-100 rounded-lg text-[10px] font-bold uppercase tracking-widest flex items-center justify-center gap-2 active:scale-[0.98] transition-all hover:bg-red-500 hover:text-white disabled:opacity-30 disabled:pointer-events-none"
            >
              <i className="fa-solid fa-trash-sweep"></i> 清空全部紀錄
            </button>
          </div>
        </div>

        <div className="flex-1 overflow-y-auto custom-scrollbar p-2 bg-slate-50/50 pb-20 lg:pb-3">
           <div className="grid grid-cols-2 gap-2 pb-10 px-1">
             {visibleCards.length === 0 ? (
                <div className="col-span-2 flex flex-col items-center justify-center py-10 text-slate-400">
                  <i className="fa-regular fa-folder-open text-3xl mb-2 opacity-50"></i>
                  <span className="text-xs font-medium">尚無資料</span>
                </div>
             ) : (
                visibleCards.map(c => (
                  <div key={c.id} onClick={() => { setSelectedCardId(c.id); setViewMode('detail'); if(isMobile) setIsSidebarOpen(false); }} className={`group relative p-3 rounded-xl cursor-pointer transition-all duration-200 border flex flex-col items-center text-center gap-2 active:scale-[0.98] ${selectedCardId === c.id ? 'bg-white border-indigo-500 shadow-lg shadow-indigo-100' : 'bg-white border-slate-200/60 hover:border-slate-300'}`}>
                    <button 
                      onClick={(e) => handleDeleteCard(e, c.id)}
                      className="absolute top-2 right-2 w-6 h-6 bg-red-50 text-red-500 rounded-full opacity-0 group-hover:opacity-100 transition-opacity flex items-center justify-center hover:bg-red-500 hover:text-white"
                    >
                      <i className="fa-solid fa-trash-can text-[10px]"></i>
                    </button>
                    <div className={`w-9 h-9 rounded-full flex items-center justify-center text-xs font-bold shrink-0 ${selectedCardId === c.id ? 'bg-indigo-50 text-indigo-600' : 'bg-slate-100 text-slate-500'}`}>{c.lastName.charAt(0)}{c.firstName.charAt(0)}</div>
                    <div className="w-full min-w-0">
                      <div className={`font-bold text-[12px] mb-0.5 tracking-tight truncate ${selectedCardId === c.id ? 'text-indigo-900' : 'text-slate-700'}`}>{c.firstName} {c.lastName}</div>
                      <div className="text-[9px] font-medium text-slate-400 truncate uppercase tracking-wide">{c.company}</div>
                    </div>
                  </div>
               ))
             )}
           </div>
        </div>
      </aside>

      {/* Main Content */}
      <main className="flex-1 flex flex-col min-w-0 bg-slate-50 relative h-full overflow-hidden">
        <header className={`h-16 px-4 lg:px-6 border-b border-slate-200 flex items-center justify-between bg-white/80 backdrop-blur-xl shrink-0 z-[60] ${viewMode === 'detail' && isMobile ? 'hidden' : 'flex'}`} style={{ paddingTop: 'var(--sat)' }}>
           <div className="flex items-center gap-3 w-full">
             {isMobile && <button onClick={() => setIsSidebarOpen(true)} className="w-10 h-10 flex items-center justify-center bg-white border border-slate-200 rounded-xl shadow-sm"><i className="fa-solid fa-bars-staggered"></i></button>}
             <nav className="flex items-center bg-slate-100 p-1 rounded-2xl overflow-x-auto no-scrollbar gap-1 flex-1 lg:flex-none">
                {isMobile && <NavBtn icon="fa-camera" label="掃描" active={viewMode === 'camera'} onClick={() => setViewMode('camera')} />}
                <NavBtn icon={isMobile ? "fa-upload" : "fa-print"} label={isMobile ? "上傳" : "掃描匯入"} active={viewMode === 'file'} onClick={() => setViewMode('file')} />
                <NavBtn icon="fa-list-check" label="任務" active={viewMode === 'tasks'} onClick={() => setViewMode('tasks')} />
                {selectedCardId && (
                  <>
                    <div className="w-px h-4 bg-slate-300 mx-1 shrink-0"></div>
                    <NavBtn icon="fa-id-card" label="核對" active={viewMode === 'detail'} onClick={() => setViewMode('detail')} />
                  </>
                )}
             </nav>
           </div>
        </header>

        <div className="flex-1 relative overflow-hidden">
          {viewMode === 'camera' && (
            <div className="h-full p-4 lg:p-8 animate-fadeIn">
              <CameraScanner onCapture={async (b64) => { 
                  const id = crypto.randomUUID(); const res = await fetch(`data:image/jpeg;base64,${b64}`);
                  const blob = await res.blob(); filesMap.current.set(id, blob);
                  setTasks(prev => [...prev, { id, fileName: `SCAN_${Date.now()}`, status: 'pending', progress: 0, batchIndex: 1, previewUrl: `data:image/jpeg;base64,${b64}` }]);
                  setViewMode('tasks');
              }} onClose={() => setViewMode('file')} />
            </div>
          )}

          {viewMode === 'file' && (
            <div className="h-full flex flex-col items-center justify-center p-4 lg:p-10 animate-fadeInUp">
              <div className="w-full max-w-2xl p-8 lg:p-16 border-2 border-dashed border-slate-200 rounded-[2.5rem] bg-white/80 backdrop-blur-lg text-center group shadow-lg cursor-pointer transition-all hover:border-indigo-300 relative overflow-hidden" onClick={() => fileInputRef.current?.click()}>
                    <div className="w-20 h-20 lg:w-24 lg:h-24 bg-gradient-to-br from-indigo-500 to-indigo-700 rounded-[2rem] flex items-center justify-center mx-auto mb-8 shadow-xl shadow-indigo-100 relative z-10 animate-float"><i className={`fa-solid ${isMobile ? 'fa-cloud-arrow-up' : 'fa-print'} text-3xl text-white`}></i></div>
                    <div className="relative z-10">
                        <h3 className="text-2xl lg:text-3xl font-extrabold text-slate-800 mb-3">{isMobile ? '上傳名片照片' : '匯入掃描檔案'}</h3>
                        <p className="text-slate-400 text-sm mb-10 max-w-sm mx-auto">支援 PDF, JPG, PNG 格式<br/><span className="text-indigo-500 font-bold"><i className="fa-solid fa-wand-magic-sparkles"></i> AI 自動定位名片位置</span></p>
                        <div className="inline-flex items-center gap-3 px-8 py-4 bg-indigo-600 text-white rounded-2xl text-sm font-bold uppercase tracking-widest shadow-lg group-hover:bg-indigo-700 transition-all">選擇檔案</div>
                    </div>
                <input type="file" ref={fileInputRef} className="hidden" accept="image/*,.pdf" multiple onChange={handleFileUpload} />
              </div>
            </div>
          )}

          {viewMode === 'cropper' && cropperImage && (
             <div className="h-full flex flex-col bg-slate-100 animate-fadeIn" onMouseMove={handleCropMove} onMouseUp={handleCropEnd} onTouchMove={handleCropMove} onTouchEnd={handleCropEnd}>
                <div className="flex items-center justify-between p-4 bg-white border-b border-slate-200 shrink-0 z-[100]">
                    <div className="flex items-center gap-4">
                        <div className="w-10 h-10 bg-indigo-50 text-indigo-600 rounded-xl flex items-center justify-center"><i className="fa-solid fa-crop-simple"></i></div>
                        <div>
                            <h2 className="text-[15px] font-bold text-slate-800">智慧裁切工具</h2>
                            <p className="text-[10px] font-bold uppercase tracking-wider text-slate-400">已自動定位 {cropRegions.length} 張名片</p>
                        </div>
                    </div>
                    <div className="flex gap-2">
                        {isAiDetecting && <div className="flex items-center gap-2 px-3 py-1.5 bg-indigo-50 text-indigo-600 rounded-lg animate-pulse"><i className="fa-solid fa-wand-magic-sparkles fa-spin text-xs"></i><span className="text-[10px] font-bold uppercase">AI 偵測中...</span></div>}
                        {pdfDoc && (
                            <div className="flex items-center gap-1 bg-slate-100 rounded-lg p-1">
                                <button disabled={currentPdfPage <= 1} onClick={() => { setCurrentPdfPage(p => p - 1); renderPdfPage(pdfDoc, currentPdfPage - 1); }} className="w-8 h-8 flex items-center justify-center rounded bg-white disabled:opacity-50"><i className="fa-solid fa-chevron-left text-xs"></i></button>
                                <span className="text-xs font-bold w-12 text-center">{currentPdfPage}/{pdfDoc.numPages}</span>
                                <button disabled={currentPdfPage >= pdfDoc.numPages} onClick={() => { setCurrentPdfPage(p => p + 1); renderPdfPage(pdfDoc, currentPdfPage + 1); }} className="w-8 h-8 flex items-center justify-center rounded bg-white disabled:opacity-50"><i className="fa-solid fa-chevron-right text-xs"></i></button>
                            </div>
                        )}
                        <button onClick={() => { setViewMode('file'); setCropperImage(null); setPdfDoc(null); }} className="px-4 py-2 text-xs font-bold text-slate-500 hover:bg-slate-100 rounded-lg">取消</button>
                        <button onClick={processCrops} disabled={cropRegions.length === 0} className="px-6 py-2 text-xs font-bold text-white bg-indigo-600 rounded-lg shadow-lg disabled:opacity-50 flex items-center gap-2">開始批次分析 ({cropRegions.length})</button>
                    </div>
                </div>
                <div className="flex-1 overflow-auto p-12 flex items-start justify-center relative select-none bg-slate-200/50" onMouseDown={(e) => { if (e.target === e.currentTarget) handleCropStart(e, 'draw'); }}>
                    <div className="relative shadow-2xl bg-white">
                        {isRenderingPdf && <div className="absolute inset-0 bg-white/80 z-[60] flex items-center justify-center backdrop-blur-sm animate-fadeIn"><i className="fa-solid fa-circle-notch fa-spin text-3xl text-indigo-500"></i></div>}
                        <img ref={cropperImgRef} src={cropperImage} className="max-w-none w-auto h-auto block select-none pointer-events-none" style={{ maxHeight: 'calc(100vh - 180px)' }} draggable={false} />
                        <div className="absolute inset-0 z-10" onMouseDown={(e) => handleCropStart(e, 'draw')}></div>
                        {cropRegions.map(crop => (
                            <div key={crop.id} className={`absolute border-2 z-20 group ${activeCropId === crop.id ? 'border-indigo-500 bg-indigo-500/10' : 'border-emerald-400 bg-emerald-400/10 hover:border-indigo-400'}`} style={{ left: `${crop.x}%`, top: `${crop.y}%`, width: `${crop.w}%`, height: `${crop.h}%` }} onMouseDown={(e) => { e.stopPropagation(); handleCropStart(e, 'move', crop.id); }}>
                                <div className="absolute -top-1.5 -left-1.5 w-3 h-3 bg-white border-2 border-indigo-500 rounded-full cursor-nw-resize z-30" onMouseDown={(e) => { e.stopPropagation(); handleCropStart(e, 'resize', crop.id, 'tl'); }}></div>
                                <div className="absolute -top-1.5 -right-1.5 w-3 h-3 bg-white border-2 border-indigo-500 rounded-full cursor-ne-resize z-30" onMouseDown={(e) => { e.stopPropagation(); handleCropStart(e, 'resize', crop.id, 'tr'); }}></div>
                                <div className="absolute -bottom-1.5 -left-1.5 w-3 h-3 bg-white border-2 border-indigo-500 rounded-full cursor-sw-resize z-30" onMouseDown={(e) => { e.stopPropagation(); handleCropStart(e, 'resize', crop.id, 'bl'); }}></div>
                                <div className="absolute -bottom-1.5 -right-1.5 w-3 h-3 bg-white border-2 border-indigo-500 rounded-full cursor-se-resize z-30" onMouseDown={(e) => { e.stopPropagation(); handleCropStart(e, 'resize', crop.id, 'br'); }}></div>
                                <button className="absolute -top-3 -right-3 w-6 h-6 bg-red-500 text-white rounded-full flex items-center justify-center text-[10px] shadow-lg z-40" onClick={(e) => { e.stopPropagation(); setCropRegions(prev => prev.filter(c => c.id !== crop.id)); }}><i className="fa-solid fa-xmark"></i></button>
                                <div className="absolute top-1 left-1 pointer-events-none"><span className={`text-[8px] font-black uppercase px-1.5 py-0.5 rounded shadow-sm ${activeCropId === crop.id ? 'bg-indigo-600 text-white' : 'bg-emerald-500 text-white'}`}>Card {cropRegions.indexOf(crop) + 1}</span></div>
                            </div>
                        ))}
                        {isDrawing && currentRect && <div className="absolute border-2 border-dashed border-indigo-500 bg-indigo-500/5 z-30 pointer-events-none" style={{ left: `${currentRect.x}%`, top: `${currentRect.y}%`, width: `${currentRect.w}%`, height: `${currentRect.h}%` }}></div>}
                    </div>
                </div>
                <div className="bg-white p-3 border-t border-slate-200 flex justify-center gap-8 text-[10px] font-bold text-slate-400 uppercase tracking-widest shrink-0">
                    <span className="flex items-center gap-2"><i className="fa-solid fa-mouse-pointer text-indigo-400"></i> 拖曳框選區域</span>
                    <span className="flex items-center gap-2"><i className="fa-solid fa-up-down-left-right text-indigo-400"></i> 移動位置</span>
                    <span className="flex items-center gap-2"><i className="fa-solid fa-maximize text-indigo-400"></i> 調整大小</span>
                </div>
             </div>
          )}

          {viewMode === 'tasks' && (
            <div className="max-w-2xl mx-auto p-4 lg:p-12 animate-fadeIn h-full overflow-y-auto pb-32">
              <div className="flex items-center justify-between mb-6"><h2 className="text-xl lg:text-2xl font-bold text-slate-800 tracking-tight">處理佇列</h2><span className="bg-indigo-100 text-indigo-700 px-3 py-1 rounded-full text-xs font-bold">{tasks.length} 項目</span></div>
              <div className="space-y-3">
                {tasks.map(t => (
                  <div key={t.id} className="p-4 bg-white border border-slate-100 rounded-2xl flex items-center justify-between shadow-sm">
                    <div className="flex items-center gap-4 min-w-0">
                      {t.previewUrl ? <img src={t.previewUrl} className="w-12 h-12 rounded-lg object-cover border border-slate-200 shrink-0" alt="preview" /> : <div className={`w-12 h-12 rounded-xl flex items-center justify-center shrink-0 ${t.status === 'completed' ? 'bg-emerald-50 text-emerald-600' : 'bg-indigo-50 text-indigo-600'}`}><i className={`fa-solid ${t.status === 'completed' ? 'fa-check' : t.status === 'processing' ? 'fa-circle-notch fa-spin' : 'fa-clock'}`}></i></div>}
                      <div className="min-w-0"><div className="font-bold text-slate-800 text-sm truncate mb-0.5">{t.fileName}</div><div className="text-[10px] font-bold uppercase tracking-wider text-slate-400">{t.status === 'completed' ? '已完成' : t.status === 'processing' ? 'AI 分析中...' : '等待中'}</div></div>
                    </div>
                    {t.status === 'completed' && <button onClick={() => { setSelectedCardId(t.id); setViewMode('detail'); }} className="w-8 h-8 flex items-center justify-center text-slate-300 transition-transform active:translate-x-1"><i className="fa-solid fa-chevron-right"></i></button>}
                  </div>
                ))}
              </div>
            </div>
          )}

          {viewMode === 'detail' && (
            <div className="h-full flex flex-col lg:flex-row overflow-hidden animate-fadeIn relative" key={selectedCardData?.id || 'empty'}>
               {isLoadingDetail && (
                 <div className="absolute inset-0 bg-white/60 backdrop-blur-[2px] z-[90] flex items-center justify-center animate-fadeIn">
                   <div className="flex flex-col items-center gap-4">
                     <div className="w-12 h-12 border-4 border-indigo-100 border-t-indigo-600 rounded-full animate-spin"></div>
                     <p className="text-xs font-bold text-indigo-600 uppercase tracking-widest">資料載入中...</p>
                   </div>
                 </div>
               )}

               {selectedCardData ? (
                 <>
                   <div className={`relative flex flex-col bg-black overflow-hidden shadow-inner ${isMobile ? 'h-[40vh] shrink-0' : 'w-[45%] h-full border-r border-slate-800'}`}>
                      <div className="absolute top-4 right-4 z-[70] flex gap-2">
                        <button onClick={() => setRotation(r => r + 90)} className="w-9 h-9 bg-black/40 backdrop-blur-md rounded-xl flex items-center justify-center text-white border border-white/10 transition-colors hover:bg-black/60"><i className="fa-solid fa-rotate-right"></i></button>
                        <button onClick={() => setIsImageZoomed(true)} className="w-9 h-9 bg-indigo-600 rounded-xl flex items-center justify-center text-white shadow-lg shadow-indigo-500/30 transition-transform active:scale-95"><i className="fa-solid fa-expand"></i></button>
                      </div>
                      <div ref={imgContainerRef} className="flex-1 w-full h-full relative overflow-hidden p-4">
                        {selectedCardData.imageUrl && containerDim.w > 0 && (
                          <img 
                            src={selectedCardData.imageUrl} 
                            className="shadow-2xl transition-transform duration-300 ease-out cursor-zoom-in" 
                            style={{ 
                              position: 'absolute', 
                              left: '50%', 
                              top: '50%', 
                              transform: `translate(-50%, -50%) rotate(${rotation}deg)`, 
                              maxWidth: (Math.abs(rotation) % 180 === 90) ? containerDim.h : containerDim.w, 
                              maxHeight: (Math.abs(rotation) % 180 === 90) ? containerDim.w : containerDim.h, 
                              objectFit: 'contain' 
                            }} 
                            onClick={() => setIsImageZoomed(true)} 
                          />
                        )}
                      </div>
                   </div>
                   <div className="flex-1 overflow-y-auto custom-scrollbar bg-white p-5 lg:p-12 space-y-6">
                        <header className="border-b border-slate-100 pb-6">
                          <div className="flex items-center justify-between mb-3">
                            <span className="px-2.5 py-1 bg-indigo-50 text-indigo-600 text-[10px] font-bold uppercase rounded-md inline-block">{selectedCardData.category}</span>
                            <div className="flex items-center gap-3">
                              {!isMobile && (
                                <button 
                                  onClick={() => handleShareCardExcel(selectedCardData)}
                                  disabled={isExporting}
                                  className="text-[10px] font-bold text-indigo-500 hover:text-indigo-700 uppercase tracking-widest flex items-center gap-1.5 px-3 py-1 hover:bg-indigo-50 rounded-lg transition-colors disabled:opacity-50"
                                >
                                  {isExporting ? <i className="fa-solid fa-circle-notch fa-spin"></i> : <i className="fa-solid fa-share-nodes"></i>} 分享 Excel
                                </button>
                              )}
                              <button 
                                onClick={(e) => handleDeleteCard(e, selectedCardData.id)}
                                className="text-[10px] font-bold text-red-400 hover:text-red-600 uppercase tracking-widest flex items-center gap-1.5 px-3 py-1 hover:bg-red-50 rounded-lg transition-colors"
                              >
                                <i className="fa-solid fa-trash-can"></i> 刪除紀錄
                              </button>
                            </div>
                          </div>
                          <h1 className="text-2xl font-extrabold text-slate-900 leading-tight mb-2 truncate">
                            {selectedCardData.prefix && <span className="text-slate-400 font-medium text-lg mr-2">{selectedCardData.prefix}</span>}
                            {selectedCardData.firstName} {selectedCardData.lastName}
                          </h1>
                          {selectedCardData.title && <div className="text-base font-semibold text-indigo-600">{selectedCardData.title}</div>}
                        </header>
                        <div><h3 className="text-xs font-bold text-slate-400 uppercase tracking-widest mb-4 flex items-center gap-2"><i className="fa-solid fa-building"></i> 組織資訊</h3><div className="grid grid-cols-1 md:grid-cols-2 gap-4"><Field label="Company" value={selectedCardData.company} translation={selectedCardData.translations?.company} className="md:col-span-2" /><Field label="Department" value={selectedCardData.department} translation={selectedCardData.translations?.department} /><Field label="Industry" value={selectedCardData.industry} translation={selectedCardData.translations?.industry} /></div></div>
                        <div><h3 className="text-xs font-bold text-slate-400 uppercase tracking-widest mb-4 flex items-center gap-2 pt-4 border-t border-slate-100"><i className="fa-solid fa-address-book"></i> 聯絡方式</h3><div className="grid grid-cols-1 md:grid-cols-2 gap-4"><Field label="Email" value={selectedCardData.email} icon="fa-envelope" /><Field label="Phone" value={selectedCardData.phone} icon="fa-phone" /><Field label="Website" value={selectedCardData.website} icon="fa-globe" className="md:col-span-2" /><Field label="Address" value={selectedCardData.address} icon="fa-location-dot" className="md:col-span-2" /></div></div>
                        <div><h3 className="text-xs font-bold text-slate-400 uppercase tracking-widest mb-4 flex items-center gap-2 pt-4 border-t border-slate-100"><i className="fa-solid fa-circle-info"></i> AI 分析摘要</h3><div className="p-4 bg-slate-50 rounded-xl border border-slate-100 text-xs text-slate-600 leading-relaxed">{selectedCardData.reasoning}</div></div>
                        <div className="h-24 lg:hidden"></div> {/* 手機端底部空間 */}
                   </div>
                   {isMobile && (
                     <div className="fixed bottom-0 left-0 right-0 px-4 pb-8 pt-4 bg-white/95 backdrop-blur-xl border-t border-slate-200 z-[80] flex gap-2 shadow-2xl shadow-indigo-900/10" style={{ paddingBottom: 'calc(1.5rem + var(--sab))' }}>
                       <button onClick={() => setViewMode('file')} className="flex-1 bg-slate-100 text-slate-600 py-4 rounded-2xl font-bold text-xs uppercase tracking-widest active:scale-95 transition-all border border-slate-200">返回</button>
                       <button 
                         onClick={() => handleShareCardExcel(selectedCardData)} 
                         disabled={isExporting}
                         className="flex-1 bg-indigo-50 text-indigo-600 py-4 rounded-2xl font-bold text-xs uppercase tracking-widest flex items-center justify-center gap-2 active:scale-95 transition-all border border-indigo-100 disabled:opacity-50"
                       >
                         {isExporting ? <i className="fa-solid fa-circle-notch fa-spin"></i> : <i className="fa-solid fa-share-nodes"></i>} 分享 Excel
                       </button>
                       <button 
                         onClick={() => handleShareOrExport(selectedCardData.category)} 
                         disabled={isExporting}
                         className="flex-[1.5] bg-slate-900 text-white py-4 rounded-2xl font-bold text-xs uppercase tracking-widest shadow-xl active:scale-95 transition-all flex items-center justify-center gap-2 disabled:opacity-50"
                       >
                         {isExporting ? <i className="fa-solid fa-circle-notch fa-spin"></i> : <i className="fa-solid fa-file-excel"></i>} 匯出/分享
                       </button>
                     </div>
                   )}
                 </>
               ) : !isLoadingDetail && (
                 <div className="flex-1 flex flex-col items-center justify-center text-slate-400 p-10 text-center animate-fadeInUp">
                    <i className="fa-solid fa-id-badge text-5xl mb-6 opacity-10"></i>
                    <p className="text-sm font-bold uppercase tracking-widest text-slate-300 mb-2">請在左側選擇一張名片</p>
                    <p className="text-[10px] text-slate-400">或從任務佇列點選檢查按鈕</p>
                 </div>
               )}
            </div>
          )}
        </div>

        {isImageZoomed && selectedCardData && <div className="fixed inset-0 z-[300] bg-black/95 flex items-center justify-center p-4 backdrop-blur-sm animate-fadeIn" onClick={() => setIsImageZoomed(false)}><button onClick={() => setIsImageZoomed(false)} className="absolute top-12 right-6 w-12 h-12 bg-white/10 text-white rounded-full flex items-center justify-center z-[310] transition-colors hover:bg-white/20"><i className="fa-solid fa-xmark"></i></button><div className="w-full h-full flex items-center justify-center overflow-auto no-scrollbar"><img src={selectedCardData.imageUrl} className="max-w-none w-full lg:w-auto lg:h-[90vh] object-contain shadow-2xl" style={{ transform: `rotate(${rotation}deg)` }} /></div></div>}
      </main>

      {isMobile && isSidebarOpen && <div className="fixed inset-0 bg-slate-900/50 backdrop-blur-sm z-[90] animate-fadeIn" onClick={() => setIsSidebarOpen(false)} />}
      <style>{`
        .no-scrollbar::-webkit-scrollbar { display: none; }
        .custom-scrollbar::-webkit-scrollbar { width: 4px; }
        .custom-scrollbar::-webkit-scrollbar-thumb { background: #cbd5e1; border-radius: 10px; }
        @keyframes fadeIn { from { opacity: 0; } to { opacity: 1; } }
        @keyframes fadeInUp { from { opacity: 0; transform: translateY(20px); } to { opacity: 1; transform: translateY(0); } }
        @keyframes float { 0% { transform: translateY(0px); } 50% { transform: translateY(-10px); } 100% { transform: translateY(0px); } }
        .animate-fadeIn { animation: fadeIn 0.3s ease-out forwards; }
        .animate-fadeInUp { animation: fadeInUp 0.5s cubic-bezier(0.2, 0.8, 0.2, 1) forwards; }
        .animate-float { animation: float 4s ease-in-out infinite; }
      `}</style>
    </div>
  );
};

const Field = React.memo(({ label, value, translation, icon, className }: any) => {
  if (!value || (typeof value === 'string' && !value.trim())) return null;
  const [copied, setCopied] = useState(false);
  const hasValue = Boolean(value && value.trim().length > 0);
  return (
    <div className={`group min-w-0 ${className}`}>
      <div className="flex items-center justify-between mb-1.5 px-0.5"><label className="text-[10px] font-bold text-slate-400 uppercase tracking-widest flex items-center gap-1.5">{icon && <i className={`fa-solid ${icon} text-indigo-300`}></i>} {label}</label>{hasValue && <button onClick={() => { navigator.clipboard.writeText(value); setCopied(true); setTimeout(() => setCopied(false), 2000); }} className={`text-[9px] font-bold uppercase transition-colors ${copied ? 'text-emerald-500 font-black' : 'text-indigo-400 hover:text-indigo-600'}`}>{copied ? 'COPIED' : 'COPY'}</button>}</div>
      <div className="w-full bg-slate-50 border border-slate-200 p-3.5 rounded-xl active:scale-[0.99] transition-transform relative"><div className={`text-[13px] font-semibold leading-relaxed break-all ${hasValue ? 'text-slate-700' : 'text-slate-300 italic'}`}>{hasValue ? value : 'N/A'}</div>{hasValue && translation && translation !== value && <div className="mt-2 pt-2 border-t border-slate-100 text-xs font-medium text-slate-500 italic">譯：{translation}</div>}</div>
    </div>
  );
});

const CompactTab = React.memo(({ label, active, count, onClick }: any) => (
  <button onClick={onClick} className={`flex-1 py-2 px-1 rounded-lg transition-all flex flex-col items-center justify-center min-w-0 active:scale-95 ${active ? 'bg-white text-indigo-700 shadow-sm ring-1 ring-black/5' : 'text-slate-500 hover:bg-slate-200/50'}`}>
    <span className="text-[9px] font-bold uppercase tracking-wider truncate w-full text-center">{label}</span>
    <span className={`text-[10px] font-extrabold ${active ? 'text-indigo-600' : 'text-slate-400'}`}>{count}</span>
  </button>
));

const NavBtn = React.memo(({ icon, label, active, onClick }: any) => (
  <button onClick={onClick} className={`flex items-center gap-2 py-2 px-3 rounded-xl transition-all font-bold text-[10px] uppercase tracking-wide whitespace-nowrap active:scale-95 ${active ? 'bg-slate-900 text-white shadow-lg' : 'text-slate-500 hover:bg-slate-200/60'}`}>
    <i className={`fa-solid ${icon}`}></i><span className="hidden sm:inline">{label}</span>
  </button>
));

export default App;
